-- tkdog 题库平台数据库导出
-- 生成时间: 2026-09-06T10:11:26.465Z
-- 数据库: tkdog
-- 包含: answer_record 按月分区表 + answer_record_archive 归档表 + 全量索引优化
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- Table: admin
DROP TABLE IF EXISTS `admin`;
CREATE TABLE `admin` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `password` varchar(255) NOT NULL,
  `last_login_time` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: ai_analysis
DROP TABLE IF EXISTS `ai_analysis`;
CREATE TABLE `ai_analysis` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `question_id` int(11) NOT NULL,
  `summary` varchar(500) DEFAULT '',
  `points` text DEFAULT NULL,
  `thinking` text DEFAULT NULL,
  `pitfall` text DEFAULT NULL,
  `template` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `hint` text DEFAULT NULL COMMENT 'AI答题提示（不含答案）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_question_id` (`question_id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: ai_learning_report
DROP TABLE IF EXISTS `ai_learning_report`;
CREATE TABLE `ai_learning_report` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `report` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: ai_paper_report
DROP TABLE IF EXISTS `ai_paper_report`;
CREATE TABLE `ai_paper_report` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `record_id` int(11) NOT NULL,
  `report` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_record` (`record_id`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: announcement
DROP TABLE IF EXISTS `announcement`;
CREATE TABLE `announcement` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `content` text DEFAULT NULL,
  `ctime` datetime DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: answer_record
DROP TABLE IF EXISTS `answer_record`;
CREATE TABLE `answer_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `record_id` int(11) NOT NULL COMMENT 'paper_record.id',
  `user_id` int(11) NOT NULL COMMENT '作答用户ID',
  `paper_id` int(11) NOT NULL COMMENT '试卷ID',
  `question_id` int(11) NOT NULL COMMENT '题目ID',
  `user_answer` text DEFAULT NULL COMMENT '用户作答内容',
  `is_correct` tinyint(1) DEFAULT NULL COMMENT '1对 0错 NULL主观题不判分',
  `ctime` datetime NOT NULL COMMENT '答题时间（分区键，不允许NULL）',
  `score` int(11) DEFAULT NULL,
  `max_score` int(11) NOT NULL DEFAULT 0 COMMENT '该题满分',
  PRIMARY KEY (`id`,`ctime`),
  KEY `idx_answer_record_user` (`user_id`),
  KEY `idx_answer_record_question` (`question_id`),
  KEY `idx_answer_record_record` (`record_id`),
  KEY `idx_paper_id` (`paper_id`),
  KEY `idx_ctime` (`ctime`),
  KEY `idx_user_question` (`user_id`,`question_id`),
  KEY `idx_user_ctime` (`user_id`,`ctime`)
) ENGINE=InnoDB AUTO_INCREMENT=15661 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
 PARTITION BY RANGE (to_days(`ctime`))
(PARTITION `p202607` VALUES LESS THAN (740194) ENGINE = InnoDB,
 PARTITION `p202608` VALUES LESS THAN (740225) ENGINE = InnoDB,
 PARTITION `p202609` VALUES LESS THAN (740255) ENGINE = InnoDB,
 PARTITION `p202610` VALUES LESS THAN (740286) ENGINE = InnoDB,
 PARTITION `p202611` VALUES LESS THAN (740316) ENGINE = InnoDB,
 PARTITION `p202612` VALUES LESS THAN (740347) ENGINE = InnoDB,
 PARTITION `p202701` VALUES LESS THAN (740378) ENGINE = InnoDB,
 PARTITION `p202702` VALUES LESS THAN (740406) ENGINE = InnoDB,
 PARTITION `p202703` VALUES LESS THAN (740437) ENGINE = InnoDB,
 PARTITION `p202704` VALUES LESS THAN (740467) ENGINE = InnoDB,
 PARTITION `p202705` VALUES LESS THAN (740498) ENGINE = InnoDB,
 PARTITION `p202706` VALUES LESS THAN (740528) ENGINE = InnoDB,
 PARTITION `pmax` VALUES LESS THAN MAXVALUE ENGINE = InnoDB);


-- Table: answer_record_archive
DROP TABLE IF EXISTS `answer_record_archive`;
CREATE TABLE `answer_record_archive` (
  `id` int(11) NOT NULL,
  `record_id` int(11) NOT NULL COMMENT 'paper_record.id',
  `user_id` int(11) NOT NULL COMMENT '作答用户ID',
  `paper_id` int(11) NOT NULL COMMENT '试卷ID',
  `question_id` int(11) NOT NULL COMMENT '题目ID',
  `user_answer` text DEFAULT NULL COMMENT '用户作答内容',
  `is_correct` tinyint(1) DEFAULT NULL COMMENT '1对 0错 NULL主观题不判分',
  `ctime` datetime NOT NULL COMMENT '答题时间',
  `score` int(11) DEFAULT NULL,
  `max_score` int(11) NOT NULL DEFAULT 0 COMMENT '该题满分',
  `archived_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '归档时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_record_id` (`record_id`),
  KEY `idx_ctime` (`ctime`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='答题记录归档表（90天前数据）';

-- Table: checkin
DROP TABLE IF EXISTS `checkin`;
CREATE TABLE `checkin` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL COMMENT '打卡用户ID',
  `checkin_date` date NOT NULL,
  `ctime` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_date` (`user_id`,`checkin_date`),
  KEY `idx_checkin_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11274 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: comment
DROP TABLE IF EXISTS `comment`;
CREATE TABLE `comment` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `content` text DEFAULT NULL,
  `create_time` datetime DEFAULT current_timestamp(),
  `question_id` int(11) DEFAULT NULL,
  `parent_id` int(11) DEFAULT NULL COMMENT '父评论ID（回复某条评论时使用）',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1=通过 0=待审核',
  `is_pinned` tinyint(1) NOT NULL DEFAULT 0,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `images` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_comment_question` (`question_id`),
  KEY `idx_question_id` (`question_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=3672 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: comment_like
DROP TABLE IF EXISTS `comment_like`;
CREATE TABLE `comment_like` (
  `user_id` int(11) NOT NULL,
  `comment_id` int(11) NOT NULL,
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`user_id`,`comment_id`),
  KEY `idx_comment_id` (`comment_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: examination_paper
DROP TABLE IF EXISTS `examination_paper`;
CREATE TABLE `examination_paper` (
  `author` varchar(255) NOT NULL COMMENT '试卷作者',
  `user_id` int(11) DEFAULT NULL COMMENT '作者用户ID',
  `ctime` datetime NOT NULL COMMENT '创建时间',
  `paper_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '试卷编号',
  `paper_title` varchar(255) NOT NULL COMMENT '试卷标题',
  `paper_tags` varchar(255) NOT NULL COMMENT '试卷标签',
  `purview` int(2) NOT NULL COMMENT '试卷权限',
  `chkState` int(2) NOT NULL COMMENT '审核状态',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`paper_id`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=880 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: notification
DROP TABLE IF EXISTS `notification`;
CREATE TABLE `notification` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL COMMENT '接收用户ID',
  `type` varchar(30) NOT NULL DEFAULT 'system' COMMENT '通知类型',
  `title` varchar(255) DEFAULT NULL COMMENT '标题',
  `content` varchar(500) DEFAULT NULL COMMENT '内容',
  `is_read` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0未读 1已读',
  `ctime` datetime DEFAULT NULL,
  `question_id` int(11) DEFAULT NULL COMMENT '关联题目ID',
  `comment_id` int(11) DEFAULT NULL COMMENT '关联评论ID',
  PRIMARY KEY (`id`),
  KEY `idx_notification_user` (`user_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_is_read` (`is_read`)
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: paper_question
DROP TABLE IF EXISTS `paper_question`;
CREATE TABLE `paper_question` (
  `paper_id` int(11) NOT NULL,
  `question_id` int(11) NOT NULL,
  `sort_order` int(11) DEFAULT 0,
  PRIMARY KEY (`paper_id`,`question_id`),
  KEY `idx_question_id` (`question_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: paper_record
DROP TABLE IF EXISTS `paper_record`;
CREATE TABLE `paper_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL COMMENT '作答用户ID',
  `paper_id` int(11) NOT NULL COMMENT '试卷ID',
  `score` int(11) NOT NULL DEFAULT 0,
  `question_num` int(11) NOT NULL DEFAULT 0 COMMENT '题目总数',
  `correct_num` int(11) NOT NULL DEFAULT 0 COMMENT '答对数量',
  `wrong_num` int(11) NOT NULL DEFAULT 0 COMMENT '答错数量',
  `subjective_num` int(11) NOT NULL DEFAULT 0 COMMENT '主观题（待批改）数量',
  `ctime` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_paper_record_user` (`user_id`),
  KEY `idx_paper_record_paper` (`paper_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_paper_id` (`paper_id`)
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: question_feedback
DROP TABLE IF EXISTS `question_feedback`;
CREATE TABLE `question_feedback` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `question_id` int(11) NOT NULL COMMENT '题目ID',
  `user_id` int(11) NOT NULL COMMENT '反馈用户ID',
  `type` varchar(30) DEFAULT 'error' COMMENT '反馈类型 error/wrong_answer/typo',
  `content` varchar(500) DEFAULT NULL COMMENT '反馈内容',
  `is_resolved` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已处理',
  `ctime` datetime DEFAULT NULL,
  `resolve_remark` varchar(500) DEFAULT NULL COMMENT '处理备注',
  `resolve_time` datetime DEFAULT NULL,
  `resolver` varchar(255) DEFAULT NULL COMMENT '处理人',
  PRIMARY KEY (`id`),
  KEY `idx_feedback_question` (`question_id`),
  KEY `idx_question_id` (`question_id`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=505 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: questions
DROP TABLE IF EXISTS `questions`;
CREATE TABLE `questions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `subjectID` int(11) DEFAULT NULL,
  `catalogID` int(11) DEFAULT NULL,
  `browses_num` int(11) DEFAULT NULL,
  `questionType` tinyint(1) DEFAULT NULL COMMENT '题型 0单选 1多选 2判断 3简答',
  `difficulty` tinyint(1) DEFAULT NULL COMMENT '难度 0简单 1中等 2困难',
  `question` varchar(768) DEFAULT NULL,
  `questionDetail` varchar(765) DEFAULT NULL,
  `likes_num` int(11) DEFAULT NULL,
  `favorite_num` int(11) DEFAULT 0,
  `answer` text DEFAULT NULL,
  `tags` varchar(768) DEFAULT NULL,
  `chkState` tinyint(1) DEFAULT NULL,
  `chkRemarks` varchar(768) DEFAULT NULL,
  `creator` varchar(765) DEFAULT NULL,
  `creator_id` int(11) DEFAULT NULL COMMENT '创建人用户ID(user.userId)',
  `addDate` datetime DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `updateTime` datetime DEFAULT NULL COMMENT '修改时间',
  `updateUser` varchar(255) DEFAULT NULL COMMENT '修改人',
  PRIMARY KEY (`id`),
  KEY `idx_questions_filter` (`subjectID`,`questionType`,`chkState`),
  KEY `idx_subject_id` (`subjectID`),
  KEY `idx_question_type` (`questionType`),
  KEY `idx_chk_state` (`chkState`)
) ENGINE=InnoDB AUTO_INCREMENT=1096 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: sensitive_word
DROP TABLE IF EXISTS `sensitive_word`;
CREATE TABLE `sensitive_word` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `word` varchar(100) NOT NULL COMMENT '违禁词',
  `level` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1=直接拦截 2=待审核',
  `ctime` datetime DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_word` (`word`)
) ENGINE=InnoDB AUTO_INCREMENT=334 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: session
DROP TABLE IF EXISTS `session`;
CREATE TABLE `session` (
  `id` varchar(255) NOT NULL COMMENT 'session id (cookie EGG_SESS)',
  `data` text DEFAULT NULL COMMENT 'session 序列化数据',
  `expire_at` bigint(20) DEFAULT NULL COMMENT '过期时间戳(ms)',
  `update_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_expire` (`expire_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: user
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `userId` int(20) NOT NULL AUTO_INCREMENT,
  `username` varchar(255) DEFAULT NULL COMMENT '用户名',
  `password` varchar(255) NOT NULL COMMENT '密码',
  `phone` varchar(255) DEFAULT NULL COMMENT '手机号',
  `sex` varchar(10) DEFAULT NULL COMMENT '性别',
  `email` varchar(255) DEFAULT NULL COMMENT '邮箱',
  `ctime` datetime DEFAULT NULL COMMENT '注册时间',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像',
  `last_login_time` datetime DEFAULT NULL COMMENT '最后登录时间',
  `personalIntroduction` longtext DEFAULT NULL COMMENT '个人介绍',
  `daily_goal` int(11) NOT NULL DEFAULT 0,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `ai_credit` int(11) DEFAULT 100 COMMENT 'AI调用额度',
  `credit_exchanged` int(11) DEFAULT 0 COMMENT '已兑换消耗的积分',
  `integral` int(11) DEFAULT 0 COMMENT '用户积分（落库）',
  `last_checkin_date` date DEFAULT NULL COMMENT '最后打卡日期',
  `consecutive_days` int(11) DEFAULT 0 COMMENT '连续打卡天数',
  `total_checkin` int(11) DEFAULT 0 COMMENT '累计打卡天数',
  PRIMARY KEY (`userId`),
  UNIQUE KEY `uk_phone` (`phone`)
) ENGINE=InnoDB AUTO_INCREMENT=1009 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用户';


-- Table: user_favorite_question
DROP TABLE IF EXISTS `user_favorite_question`;
CREATE TABLE `user_favorite_question` (
  `user_id` int(11) NOT NULL,
  `question_id` int(11) NOT NULL,
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`user_id`,`question_id`),
  KEY `idx_question_id` (`question_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


