INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15439, 50, 9, 876, 586, 'var是函数作用域且存在变量提升，let和const是块级作用域；const声明常量不可重新赋值。盒模型由content、padding、border、margin组成。Vue组件通信方式包括props/$emit、provide/inject、vuex/pinia、eventBus、$refs、$parent/$children等。', 0, 'Sun Sep 06 2026 01:32:29 GMT+0800 (中国标准时间)', 1, 2);
