INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15443, 50, 9, 876, 590, 'HTTP常见方法有GET、POST、PUT、DELETE、PATCH、HEAD、OPTIONS。CSS选择器优先级：!important > 内联 > id > class/伪类/属性 > 标签/伪元素 > 通配符。浏览器渲染流程：解析HTML构建DOM树，解析CSS构建CSSOM，合并为渲染树，布局Layout，绘制Paint，合成Composite。', 0, 'Sun Sep 06 2026 01:32:29 GMT+0800 (中国标准时间)', 0, 4);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15444, 50, 9, 876, 591, 'HTTP常见方法有GET、POST、PUT、DELETE、PATCH、HEAD、OPTIONS。CSS选择器优先级：!important > 内联 > id > class/伪类/属性 > 标签/伪元素 > 通配符。浏览器渲染流程：解析HTML构建DOM树，解析CSS构建CSSOM，合并为渲染树，布局Layout，绘制Paint，合成Composite。', 0, 'Sun Sep 06 2026 01:32:29 GMT+0800 (中国标准时间)', 0, 2);
