INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15551, 53, 9, 878, 586, 'let、const、var 的区别集中在作用域、提升和可变性。var：1）函数作用域，无块级作用域（{} 内声明外部可访问）；2）有变量提升（声明提升到作用域顶部但值为 undefined），声明前可用；3）可重复声明；4）会挂到 window 全局。let：1）块级作用域；2）无提升（存在暂时性死', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15552, 53, 9, 878, 587, '标准盒模型由 content（内容）、padding（内边距）、border（边框）、margin（外边距）四部分组成。CSS 默认的 content-box 模式下，width/height 只包含内容区 content，padding 和 border 另算，所以元素实际占用的总宽度 = wid', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15553, 53, 9, 878, 588, 'Vue 组件通信方式可归纳为几类：1）父传子：props 传递数据（单向数据流），子组件通过 defineProps/props 接收；2）子传父：子组件通过 $emit 触发自定义事件，父组件监听处理，配合 props 形成闭环；3）跨级/兄弟通信：事件总线（mitt、EventBus，已不推荐）', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 3, 3);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15554, 53, 9, 878, 589, 'GET 和 POST 是 HTTP 最常用的两个方法，主要区别：1）用途与语义：GET 用于获取资源，应是幂等且安全的（不改变服务器状态，可缓存、可收藏、可被浏览器预取）；POST 用于提交数据/创建资源，非幂等、不可缓存。2）参数传递：GET 参数拼接在 URL 查询字符串中（?a=1&b=2），', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15555, 53, 9, 878, 590, '受控组件与非受控组件是 React 管理表单元素的两类方式。受控组件：表单值由 React 的 state 统一管理，通过 value 绑定 state、onChange 更新 state，形成"数据驱动视图"的单向数据流。用户输入 → onChange → setState → 重渲染 → 显示新', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 3, 3);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15556, 53, 9, 878, 591, 'git merge 与 git rebase 都是整合分支的方式，区别在于提交历史的组织方式。merge：把目标分支的提交合并到当前分支，会生成一个额外的合并提交（merge commit），保留两个分支完整历史，分叉清晰可见。优点是安全、不改写历史，适合公共分支协作；缺点是历史可能出现多条交叉线，', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15557, 53, 9, 878, 592, '从输入 URL 到页面显示，分为网络与渲染两大阶段。网络阶段：1）DNS 解析域名得到 IP（先查缓存、hosts，再查 DNS 服务器）；2）TCP 三次握手建立连接（HTTPS 还需 TLS 握手协商密钥）；3）发送 HTTP 请求并接收响应；4）判断缓存：强缓存命中直接读本地，协商缓存发请求比', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15558, 53, 9, 878, 593, 'Node.js 事件循环是 Node 实现异步非阻塞 I/O 的核心机制，它让单线程的 JS 能高效处理大量并发 I/O。Node 底层用 libuv 实现事件循环，主线程执行 JS，耗时 I/O（文件读写、网络请求、数据库）交给线程池或系统内核处理，完成后把回调放入队列，事件循环按阶段依次取出执行', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15559, 53, 9, 878, 596, 'Angular 是模块化的前端框架，核心概念为组件（Component）、模块（NgModule）、服务（Service）。组件：包含模板（HTML）、样式（CSS）和类（TypeScript）的视图单元，负责渲染 UI 和交互，通过 @Component 装饰器声明，是应用最基本的构建块。模块：用', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15560, 53, 9, 878, 600, 'loader 与 plugin 是 Webpack 的两大扩展机制，职责完全不同。loader：处理模块源代码的转换，是"文件级"处理。Webpack 本身只能识别 JS，loader 负责把各种非 JS 资源（CSS、Less、图片、字体、TS、Vue 文件等）转换成 Webpack 能处理的模块', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15561, 53, 9, 878, 604, '重排（回流，Reflow/Layout）是重新计算元素的几何位置和大小，重绘（Repaint/Paint）是重新绘制元素的外观（颜色、背景等）。重排一定会触发重绘，重绘不一定重排。触发重排的操作：1）增删改 DOM 元素；2）修改元素尺寸（宽高、padding、border、margin）或位置；3', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15562, 53, 9, 878, 608, 'HTTP/2 相比 HTTP/1.1 的主要改进：1）二进制分帧协议——把文本格式的报文改成二进制帧（Headers 帧、Data 帧等），解析更高效、更安全，也为多路复用打基础；2）多路复用（Multiplexing）——在一个 TCP 连接上并行交错地发送多个请求/响应，彻底解决了 HTTP/1', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15563, 53, 9, 878, 612, 'Node.js 中 require 查找模块的规则（CommonJS）：1）如果是内置核心模块（如 fs、path、http），直接返回，不再查找；2）如果是相对路径（./、../）或绝对路径，按路径解析——先尝试精确文件，再尝试加 .js、.json、.node 后缀，再尝试同名目录（读取目录下的', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15564, 53, 9, 878, 666, '深拷贝与浅拷贝的区别在于对嵌套对象的复制深度。浅拷贝：只复制对象第一层属性，若属性值是引用类型（对象/数组），复制的是引用地址，新旧对象共享该嵌套对象，修改会互相影响。常见方式：Object.assign({},obj)、展开运算符 {...obj}、数组 slice/concat。深拷贝：递归复制', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15565, 53, 9, 878, 667, '事件冒泡和事件捕获是浏览器事件传播的两个阶段，共同构成事件流。事件传播顺序（从 window 出发）：捕获阶段（window→document→...→目标元素祖先→目标元素）→ 目标阶段 → 冒泡阶段（目标元素→祖先→...→document→window）。捕获阶段：事件从最外层 window ', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15566, 53, 9, 878, 668, '标准盒模型与 IE 盒模型（即 content-box 与 border-box）的区别在于 width/height 的计算范围。标准盒模型（content-box，CSS 默认）：width/height 只包含内容区 content，padding 和 border 另算，实际总宽度 = wi', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15567, 53, 9, 878, 669, 'Vue 中 v-if 与 v-show 都能控制元素的显示/隐藏，但实现机制和适用场景不同。v-if：是"条件渲染"——为 false 时元素根本不会渲染到 DOM 中（连占位都没有），为 true 时才创建并插入；切换时会触发组件的创建/销毁（mounted/unmounted），有更高的切换开销', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15568, 53, 9, 878, 670, 'useState 是 React Hooks 中最基础的状态钩子，用于在函数组件中声明和使用局部状态。用法：const [state, setState] = useState(initialValue)，返回一个数组：state 是当前状态值，setState 是更新函数。特点：1）每次渲染 us', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15569, 53, 9, 878, 671, 'Node.js 中 require（CommonJS）与 import（ES Module）是两种模块规范的引入语法，核心区别在加载时机和机制。require：1）运行时加载，模块在代码执行到该语句时才加载，可写在条件语句中动态加载；2）同步加载，加载完才继续执行；3）导出的是值的拷贝（module', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15570, 53, 9, 878, 672, 'git fetch 与 git pull 都是从远程仓库获取更新，区别在于是否合并到当前工作分支。git fetch：只把远程仓库的最新提交下载到本地远程跟踪分支（如 origin/main），不会修改你当前工作区的任何内容，也不自动合并。它让你先"看看"远程有什么变化，是安全的只读操作。git p', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15571, 53, 9, 878, 673, 'HTTP 与 HTTPS 的核心区别在于安全性。1）加密：HTTP 明文传输，数据可被窃听；HTTPS 在 HTTP 之下增加 SSL/TLS 加密层，对传输内容加密，即使被截获也无法直接读取。2）身份认证：HTTPS 需向 CA 申请数字证书，用于验证服务器身份、防止中间人伪装；HTTP 没有身份', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15572, 53, 9, 878, 674, '浏览器事件循环（Event Loop）是 JS 单线程实现异步非阻塞的核心机制，用于协调同步代码、微任务和宏任务的执行顺序。执行流程：1）执行同步代码（当前宏任务，即 script）；2）执行结束后清空整个微任务队列（Promise.then/catch、queueMicrotask、Mutatio', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15573, 53, 9, 878, 675, 'TypeScript 中 interface 和 type 都能定义类型，区别：interface：1）只能描述对象/函数/类的结构；2）支持 extends 继承（接口继承接口、类实现）；3）支持声明合并——同名 interface 自动合并，利于扩展第三方库类型；4）更贴近 OOP 语义。typ', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15574, 53, 9, 878, 676, 'Webpack 的基本打包流程：1）初始化——读取配置文件（webpack.config.js），创建 Compiler 对象，注册插件（插件在 compiler 的各生命周期钩子上挂载）；2）确定入口——根据 Entry 配置找到入口文件，从入口开始构建依赖图；3）模块解析——解析每个模块的依赖（', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15575, 53, 9, 878, 677, 'HTML 语义化标签的作用：1）提升可读性和可维护性——用 header、nav、main、article、section、aside、footer 等标签明确表达页面结构，开发者（尤其团队协作）一眼看懂内容区块的含义；2）利于 SEO——搜索引擎爬虫能更好地理解页面内容结构，标题层级（h1-h6）', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15576, 53, 9, 878, 684, '闭包是指一个函数能够访问并记住其定义时所在词法作用域中变量的能力：即使外部函数已经执行完毕返回，这些变量依然被内部函数持有、不会被销毁。本质是函数定义时就确定了作用域链，内部函数沿链总能找到外层变量。主要作用：1）数据私有化/封装，外部无法直接访问和修改内部状态；2）延长变量生命周期，实现缓存与记忆', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15577, 53, 9, 878, 689, 'Vue 3 的响应式基于 ES6 的 Proxy 实现，通过 new Proxy(target, handler) 代理整个对象，在 get 拦截器中做依赖收集（track），在 set、deleteProperty 等拦截器中触发更新（trigger）。工作流程：1）创建响应式对象时用 Proxy', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15578, 53, 9, 878, 693, '受控组件与非受控组件是 React 管理表单元素的两类方式。受控组件：表单值由 React 的 state 统一管理，通过 value 绑定 state、onChange 更新 state，形成"数据驱动视图"的单向数据流。用户输入 → onChange → setState → 重渲染 → 显示新', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15579, 53, 9, 878, 697, 'type 和 interface 都能定义类型，但各有侧重。interface 特点：1）可被 extends 继承，支持接口继承、类实现；2）支持声明合并——同名 interface 自动合并，便于扩展第三方库类型；3）主要描述对象、函数、类的结构形状。type 特点：1）更灵活，除了对象还能定义', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15580, 53, 9, 878, 701, 'HTTP 与 HTTPS 的核心区别在于安全性。1）加密：HTTP 明文传输，数据可被窃听；HTTPS 在 HTTP 之下增加 SSL/TLS 加密层，对传输内容加密，即使被截获也无法直接读取。2）身份认证：HTTPS 需向 CA 申请数字证书，用于验证服务器身份、防止中间人伪装；HTTP 没有身份', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 1, 1);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15581, 53, 9, 878, 703, '从输入 URL 到页面渲染完成，分为网络与渲染两大阶段。网络阶段：1）DNS 解析域名得到 IP（先查缓存、hosts，再查 DNS 服务器）；2）TCP 三次握手建立连接（HTTPS 还需 TLS 握手协商密钥）；3）发送 HTTP 请求并接收响应；4）判断缓存：强缓存命中直接读本地，协商缓存发请', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15582, 53, 9, 878, 707, 'git merge 与 git rebase 都是整合分支的方式，区别在于提交历史的组织方式。merge：把目标分支的提交合并到当前分支，会生成一个额外的合并提交（merge commit），保留两个分支完整历史，分叉清晰可见。优点是安全、不改写历史，适合公共分支协作；缺点是历史可能出现多条交叉线，', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15583, 53, 9, 878, 709, 'loader 与 plugin 是 Webpack 的两大扩展机制，职责完全不同。loader：处理模块源代码的转换，是"文件级"处理。Webpack 本身只能识别 JS，loader 负责把各种非 JS 资源（CSS、Less、图片、字体、TS、Vue 文件等）转换成 Webpack 能处理的模块', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15584, 53, 9, 878, 710, 'JavaScript 数据类型分为原始类型和引用类型。原始类型 7 种：string、number、boolean、null、undefined、symbol（ES6，唯一标识）、bigint（ES2020，大整数）。引用类型：object，包括普通对象、数组、函数、Date、RegExp、Map、', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15585, 53, 9, 878, 711, 'null 和 undefined 都表示"空"，但语义和产生场景不同。undefined 表示"变量已声明但未赋值"，是系统默认值。产生场景：声明变量未赋值、函数没有 return（返回 undefined）、访问对象不存在的属性、函数参数未传时形参为 undefined。null 表示"空值/空对', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15586, 53, 9, 878, 712, '== 与 === 的区别在于是否进行类型转换。==（宽松相等）：比较前做隐式类型转换，把两个操作数转成相同类型再比。例如 1=="1" 为 true、null==undefined 为 true、[]==false 为 true、0=="" 为 true。===（严格相等）：不转换类型，类型和值都相', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 1, 1);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15587, 53, 9, 878, 714, 'isNaN 与 Number.isNaN 都能判断 NaN，但行为本质不同。isNaN（全局函数）：会先把参数强制转换为数字再判断，所以 isNaN("abc") 返回 true（"abc" 转数字失败得 NaN），isNaN("123") 返回 false（"123" 能转成 123）。它判断的是', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15588, 53, 9, 878, 715, 'let、const、var 的区别集中在作用域、提升和可变性。var：1）函数作用域，无块级作用域（{} 内声明外部可访问）；2）有变量提升（声明提升到作用域顶部但值为 undefined），声明前可用；3）可重复声明；4）会挂到 window 全局。let：1）块级作用域；2）无提升（存在暂时性死', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15589, 53, 9, 878, 717, '箭头函数是 ES6 的简写函数，与普通函数有多个本质区别。1）this 指向：箭头函数没有自己的 this，继承定义时所在外层作用域（词法作用域），且无法被 call/apply/bind 改变；普通函数 this 由调用方式决定。2）构造函数：箭头函数没有 prototype、不能 new；普通函', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
INSERT INTO `answer_record` (`id`, `record_id`, `user_id`, `paper_id`, `question_id`, `user_answer`, `is_correct`, `ctime`, `score`, `max_score`) VALUES (15590, 53, 9, 878, 719, 'call、apply、bind 都是 Function.prototype 上用于显式改变 this 指向的方法，区别在调用方式和参数。call：立即执行，参数逐个传入，fn.call(thisArg, arg1, arg2)。apply：立即执行，参数以数组传入，fn.apply(thisArg,', 1, 'Sun Sep 06 2026 01:59:19 GMT+0800 (中国标准时间)', 2, 2);
