INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (599, 7, 0, 0, 2, 0, 'Webpack 的 mode 支持 development 和 production 两种模式。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'Webpack,基础', 1, NULL, 'admin', 1, 'Sun Aug 16 2026 00:14:35 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (600, 7, 0, 0, 3, 1, '请简述 Webpack 中 loader 与 plugin 的区别。', '', 0, 0, 'loader 与 plugin 是 Webpack 的两大扩展机制，职责完全不同。loader：处理模块源代码的转换，是"文件级"处理。Webpack 本身只能识别 JS，loader 负责把各种非 JS 资源（CSS、Less、图片、字体、TS、Vue 文件等）转换成 Webpack 能处理的模块，本质是一个转换函数，在模块加载/编译阶段执行，可链式调用（从右到左，如 style-loader→css-loader→sass-loader）。典型：babel-loader 转译 ES6+、css-loader 解析 CSS、vue-loader 解析 .vue。plugin：扩展 Webpack 整个打包流程能力，是"构建级"处理，可在打包生命周期钩子上做复杂操作：代码压缩（TerserPlugin）、生成 HTML（HtmlWebpackPlugin）、提取 CSS（MiniCssExtractPlugin）、环境变量注入（DefinePlugin）、模块分包（SplitChunksPlugin）等。一句话区分：loader 在打包输入阶段转换单个文件，plugin 在打包全过程增强功能。', 'Webpack,基础', 1, NULL, 'admin', 1, 'Sun Aug 16 2026 00:14:35 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (601, 7, 0, 0, 1, 1, '以下哪些是常见的前端构建工具？', '[{"code":"A","value":"Webpack"},{"code":"B","value":"Vite"},{"code":"C","value":"Rollup"},{"code":"D","value":"Parcel"}]', 0, 0, '正确选项：ABCD', 'Webpack,构建工具', 1, NULL, 'admin', 1, 'Sun Aug 16 2026 00:14:35 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (602, 11, 0, 0, 0, 0, '以下哪个不是浏览器渲染引擎？', '[{"code":"A","value":"Blink"},{"code":"B","value":"Gecko"},{"code":"C","value":"WebKit"},{"code":"D","value":"Node.js"}]', 0, 0, '正确选项：D', '浏览器,渲染引擎', 1, NULL, 'admin', 1, 'Sun Aug 16 2026 00:14:35 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (603, 11, 0, 0, 2, 0, 'localStorage 中的数据在浏览器关闭后仍会保留。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', '浏览器,存储', 1, NULL, 'admin', 1, 'Sun Aug 16 2026 00:14:35 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (604, 11, 0, 1, 3, 2, '请简述浏览器重排（reflow）与重绘（repaint）的区别。', '', 0, 0, '重排（回流，Reflow/Layout）是重新计算元素的几何位置和大小，重绘（Repaint/Paint）是重新绘制元素的外观（颜色、背景等）。重排一定会触发重绘，重绘不一定重排。触发重排的操作：1）增删改 DOM 元素；2）修改元素尺寸（宽高、padding、border、margin）或位置；3）修改窗口尺寸（resize）、字体大小变化；4）读取某些布局属性会强制同步重排（offsetWidth、clientHeight、getBoundingClientRect、scrollTop 等，读取时强制浏览器先完成布局）；5）display:none 隐藏、增删样式类。触发重绘：颜色、背景、阴影、边框样式等视觉变化，不动几何。如何避免：1）合并 DOM 读写，用 DocumentFragment 批量操作；2）用 class 或 cssText 一次性改样式而非逐条；3）动画用 transform 实现（在合成层，不触发重排重绘）；4）避免频繁读取布局属性，缓存计算结果；5）用 display:none 先隐藏再操作；6）用 will-change/translateZ 提升为独立图层。面试常考：重排重绘区别、哪些操作触发重排、如何优化。', '浏览器,性能', 1, NULL, 'admin', 1, 'Sun Aug 16 2026 00:14:35 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (605, 11, 0, 0, 1, 1, '浏览器同源策略由哪些部分构成？', '[{"code":"A","value":"协议"},{"code":"B","value":"域名"},{"code":"C","value":"端口"},{"code":"D","value":"路径"}]', 0, 0, '正确选项：ABC', '浏览器,同源策略', 1, NULL, 'admin', 1, 'Sun Aug 16 2026 00:14:35 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (606, 10, 0, 0, 0, 1, 'HTTP 响应头中用于缓存控制的是？', '[{"code":"A","value":"Cache-Control"},{"code":"B","value":"Content-Type"},{"code":"C","value":"Accept"},{"code":"D","value":"Cookie"}]', 0, 0, '正确选项：A', 'HTTP,缓存', 1, NULL, 'admin', 1, 'Sun Aug 16 2026 00:14:35 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (607, 10, 0, 0, 2, 0, '状态码 404 表示请求的资源未找到。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'HTTP,状态码', 1, NULL, 'admin', 1, 'Sun Aug 16 2026 00:14:35 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (608, 10, 0, 1, 3, 1, '请简述 HTTP/2 相比 HTTP/1.1 的主要改进。', '', 0, 0, 'HTTP/2 相比 HTTP/1.1 的主要改进：1）二进制分帧协议——把文本格式的报文改成二进制帧（Headers 帧、Data 帧等），解析更高效、更安全，也为多路复用打基础；2）多路复用（Multiplexing）——在一个 TCP 连接上并行交错地发送多个请求/响应，彻底解决了 HTTP/1.1 的队头阻塞（应用层），页面加载速度大幅提升；3）头部压缩（HPACK）——用静态表+动态表+哈夫曼编码压缩请求/响应头，减少重复头部（如 Cookie、UA）的传输体积；4）服务器推送（Server Push）——服务器可主动推送客户端可能需要的资源（如 HTML 引用的 CSS/JS），减少请求往返；5）流量优先级和依赖——可指定流的优先级，重要资源先加载。需要注意：HTTP/2 底层仍是 TCP，TCP 层的丢包重传仍可能造成队头阻塞（这是 HTTP/3 用 QUIC/UDP 要解决的问题）。面试常考：多路复用如何解决队头阻塞、头部压缩原理、与 HTTP/3 的关系。', 'HTTP,协议', 1, NULL, 'admin', 1, 'Sun Aug 16 2026 00:14:35 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (609, 10, 0, 0, 1, 0, '以下哪些是 HTTP 常见的请求头？', '[{"code":"A","value":"User-Agent"},{"code":"B","value":"Content-Type"},{"code":"C","value":"Accept"},{"code":"D","value":"Authorization"}]', 0, 0, '正确选项：ABCD', 'HTTP,请求头', 1, NULL, 'admin', 1, 'Sun Aug 16 2026 00:14:35 GMT+0800 (中国标准时间)', 0, NULL, NULL);
