INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (666, 0, 0, 2, 3, 1, '请简述深拷贝与浅拷贝的区别。', '', 0, 0, '深拷贝与浅拷贝的区别在于对嵌套对象的复制深度。浅拷贝：只复制对象第一层属性，若属性值是引用类型（对象/数组），复制的是引用地址，新旧对象共享该嵌套对象，修改会互相影响。常见方式：Object.assign({},obj)、展开运算符 {...obj}、数组 slice/concat。深拷贝：递归复制所有层级，得到完全独立的新对象，修改互不影响。实现：1）JSON.parse(JSON.stringify(obj))——简单但有缺陷：丢失函数、undefined、Symbol，RegExp/Date 会被转成字符串或对象，无法处理循环引用；2）structuredClone()——浏览器原生，可处理 Date、Map、Set 等；3）手写递归深拷贝——用 WeakMap 记录已拷贝对象以处理循环引用，并对数组、Date、RegExp 分别处理。面试常考：JSON 深拷贝的缺陷、手写深拷贝处理循环引用。', 'JavaScript,对象', 1, '审核通过', 'admin', 1, 'Mon Aug 24 2026 22:47:55 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (667, 0, 0, 0, 3, 1, '请简述事件冒泡与事件捕获的区别。', '', 0, 0, '事件冒泡和事件捕获是浏览器事件传播的两个阶段，共同构成事件流。事件传播顺序（从 window 出发）：捕获阶段（window→document→...→目标元素祖先→目标元素）→ 目标阶段 → 冒泡阶段（目标元素→祖先→...→document→window）。捕获阶段：事件从最外层 window 逐层向下传播到目标元素，addEventListener 第三个参数为 true 时在捕获阶段触发。冒泡阶段：事件从目标元素逐层向上冒泡回 window，默认事件处理在冒泡阶段执行（第三个参数默认 false）。作用：冒泡是事件委托的基础（父元素能收到子元素冒泡上来的事件）；捕获常用于在到达目标前拦截事件。面试常考：如何阻止冒泡（stopPropagation）、stopImmediatePropagation 区别、事件流顺序。', 'JavaScript,事件', 1, '审核通过', 'admin', 1, 'Mon Aug 24 2026 22:47:55 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (668, 1, 0, 0, 3, 1, '请简述标准盒模型与 IE 盒模型的区别。', '', 0, 0, '标准盒模型与 IE 盒模型（即 content-box 与 border-box）的区别在于 width/height 的计算范围。标准盒模型（content-box，CSS 默认）：width/height 只包含内容区 content，padding 和 border 另算，实际总宽度 = width + padding + border；例如设置 width:100px + padding:20px + border:1px，实际渲染宽度 142px，容易超出预期。IE 盒模型（border-box，老 IE 及可通过 box-sizing:border-box 启用）：width/height 包含 content+padding+border，即设置的宽度就是元素总宽度，padding 和 border 向内挤压内容区；例如同样设置 width:100px + padding:20px + border:1px，总宽始终是 100px，内容区被压缩为 58px。border-box 布局更直观、不易出问题，现代开发普遍全局设置 *{ box-sizing:border-box; }。面试常考：两种盒模型计算、如何切换（box-sizing）、推荐哪种。', 'CSS,盒模型', 1, '审核通过', 'admin', 1, 'Mon Aug 24 2026 22:47:55 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (669, 5, 0, 1, 3, 2, '请简述 Vue 中 v-if 与 v-show 的区别。', '', 0, 0, 'Vue 中 v-if 与 v-show 都能控制元素的显示/隐藏，但实现机制和适用场景不同。v-if：是"条件渲染"——为 false 时元素根本不会渲染到 DOM 中（连占位都没有），为 true 时才创建并插入；切换时会触发组件的创建/销毁（mounted/unmounted），有更高的切换开销（初始渲染开销小，因为不渲染就不占 DOM）。适合"运行中很少切换、一次性决定显隐"的场景。v-show：是"样式切换"——元素始终渲染在 DOM 中，只是通过 display:none 隐藏，切换只改 CSS 样式，不涉及组件销毁重建，切换开销小（但初始就渲染，初始开销较大）。适合"频繁切换显隐"的场景。选择建议：频繁切换用 v-show，否则用 v-if；同时 v-if 与 v-for 不要在同一元素混用。面试常考：两者原理、初始开销与切换开销的取舍。', 'Vue,指令', 1, '审核通过', 'admin', 1, 'Mon Aug 24 2026 22:47:55 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (670, 4, 0, 0, 3, 2, '请简述 React 中 useState 的作用。', '', 0, 0, 'useState 是 React Hooks 中最基础的状态钩子，用于在函数组件中声明和使用局部状态。用法：const [state, setState] = useState(initialValue)，返回一个数组：state 是当前状态值，setState 是更新函数。特点：1）每次渲染 useState 返回当前最新的 state，组件状态在多次渲染间被保留；2）调用 setState 会触发组件重新渲染，更新后的 state 在下一次渲染生效（异步批量更新，同一事件中的多次 setState 会合并）；3）setState 可以是值也可以是函数（函数式更新，接收旧值返回新值，适合依赖旧值的更新，如 setCount(c=>c+1)）；4）initialValue 只在首次渲染时生效，若初始值需要昂贵计算可传函数（惰性初始化）；5）多个 useState 各自独立。与类组件 this.state 对应。面试常考：为什么 setState 是异步的、函数式更新的作用、多次更新的合并。', 'React,Hooks', 1, '审核通过', 'admin', 1, 'Mon Aug 24 2026 22:47:55 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (671, 6, 0, 0, 3, 1, '请简述 Node.js 中 require 与 import 的区别。', '', 0, 0, 'Node.js 中 require（CommonJS）与 import（ES Module）是两种模块规范的引入语法，核心区别在加载时机和机制。require：1）运行时加载，模块在代码执行到该语句时才加载，可写在条件语句中动态加载；2）同步加载，加载完才继续执行；3）导出的是值的拷贝（module.exports）；4）已加载模块会被缓存。import：1）静态加载，import 声明会被提升，编译阶段就确定依赖关系，不能动态条件导入（可用 import() 实现按需加载）；2）支持 tree-shaking，因静态可分析能剔除未使用导出；3）导出的是值的引用（实时绑定），支持具名导出和默认导出；4）浏览器原生支持，天然异步加载不阻塞。Node 现在也支持 ES Module（.mjs 或 type: module），新项目推荐使用。面试常考：两者加载时机、循环引用处理差异、tree-shaking 原理。', 'Node,模块', 1, '审核通过', 'admin', 1, 'Mon Aug 24 2026 22:47:55 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (672, 9, 0, 0, 3, 1, '请简述 git fetch 与 git pull 的区别。', '', 0, 0, 'git fetch 与 git pull 都是从远程仓库获取更新，区别在于是否合并到当前工作分支。git fetch：只把远程仓库的最新提交下载到本地远程跟踪分支（如 origin/main），不会修改你当前工作区的任何内容，也不自动合并。它让你先"看看"远程有什么变化，是安全的只读操作。git pull：等价于 git fetch + git merge（默认），即先获取远程更新，再自动合并到当前分支。如果本地和远程都有修改，可能会触发合并冲突。使用建议：想了解远程更新但不影响当前工作 → 用 fetch；想直接同步并合并到本地 → 用 pull。更稳妥的工作流是先 fetch 再手动查看/合并，避免 pull 自动合并带来意外冲突；也可用 git pull --rebase 用变基方式合并保持历史线性。面试常考：两者区别、pull 的本质、何时用 fetch。', 'Git,命令', 1, '审核通过', 'admin', 1, 'Mon Aug 24 2026 22:47:55 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (673, 10, 0, 0, 3, 1, '请简述 HTTP 与 HTTPS 的区别。', '', 0, 0, 'HTTP 与 HTTPS 的核心区别在于安全性。1）加密：HTTP 明文传输，数据可被窃听；HTTPS 在 HTTP 之下增加 SSL/TLS 加密层，对传输内容加密，即使被截获也无法直接读取。2）身份认证：HTTPS 需向 CA 申请数字证书，用于验证服务器身份、防止中间人伪装；HTTP 没有身份校验。3）完整性：HTTPS 通过消息摘要/签名校验数据在传输中是否被篡改。4）端口：HTTP 默认 80，HTTPS 默认 443。5）性能：HTTPS 因握手和加解密多些开销，但 TLS 1.3、会话复用已使其接近 HTTP 性能。原理：采用"非对称加密协商密钥 + 对称加密传输数据"——握手阶段用非对称加密（RSA/ECDHE）协商出会话密钥，之后用对称加密（AES）高效传输，兼顾安全与速度。浏览器地址栏的锁图标表示 HTTPS 生效。', 'HTTP,安全', 1, '审核通过', 'admin', 1, 'Mon Aug 24 2026 22:47:55 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (674, 11, 0, 0, 3, 1, '请简述浏览器事件循环 Event Loop 的机制。', '', 0, 0, '浏览器事件循环（Event Loop）是 JS 单线程实现异步非阻塞的核心机制，用于协调同步代码、微任务和宏任务的执行顺序。执行流程：1）执行同步代码（当前宏任务，即 script）；2）执行结束后清空整个微任务队列（Promise.then/catch、queueMicrotask、MutationObserver、async/await 后续）；3）从宏任务队列取出一个宏任务（setTimeout、setInterval、I/O、DOM 事件、AJAX 回调）执行；4）再清空所有微任务；5）循环往复，浏览器还会在合适时机执行渲染。关键规则：每个宏任务执行完后，必须把当前所有微任务执行完才进入下一个宏任务，微任务优先级高于宏任务。典型例题：console.log(1); setTimeout(()=>console.log(2),0); Promise.resolve().then(()=>console.log(3)); console.log(4); 输出为 1→4→3→2。面试常考：宏任务/微任务列表、async/await 在事件循环中的位置、Node 与浏览器差异。', '浏览器,原理', 1, '审核通过', 'admin', 1, 'Mon Aug 24 2026 22:47:55 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (675, 8, 0, 0, 3, 1, '请简述 TypeScript 中 interface 与 type 的区别。', '', 0, 0, 'TypeScript 中 interface 和 type 都能定义类型，区别：interface：1）只能描述对象/函数/类的结构；2）支持 extends 继承（接口继承接口、类实现）；3）支持声明合并——同名 interface 自动合并，利于扩展第三方库类型；4）更贴近 OOP 语义。type：1）更灵活，可定义联合类型、交叉类型、元组、字面量、基本类型别名等任意组合类型；2）不可重复声明同名 type（重复报错）；3）通过交叉（A & B）可模拟继承但语义上不是继承；4）支持映射类型、条件类型等高级类型编程。选择建议：描述对象结构、需要继承/合并、类相关用 interface；需要联合、交叉、元组或类型编程用 type。社区实践：库作者常用 interface 定义对外 API 结构（可合并扩展），内部类型用 type。面试常考：两者能力差异、声明合并、什么时候混用。', 'TypeScript,类型', 1, '审核通过', 'admin', 1, 'Mon Aug 24 2026 22:47:55 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (676, 7, 0, 1, 3, 1, '请简述 Webpack 的基本打包流程。', '', 0, 0, 'Webpack 的基本打包流程：1）初始化——读取配置文件（webpack.config.js），创建 Compiler 对象，注册插件（插件在 compiler 的各生命周期钩子上挂载）；2）确定入口——根据 Entry 配置找到入口文件，从入口开始构建依赖图；3）模块解析——解析每个模块的依赖（通过 import/require 分析），对非 JS 资源调用对应 loader 转换，把模块编译成 JS 可执行代码；4）构建依赖图——递归解析所有模块，形成完整的模块依赖关系图（ModuleGraph），并做 tree-shaking（删除未使用导出）；5）生成 chunk——按入口/分包策略（SplitChunksPlugin）把模块分组打包成 chunk；6）输出资源——把每个 chunk 编译成最终文件，经插件处理（压缩、加 hash、生成 HTML 等），写入 output 配置的输出目录（如 dist）。整个过程的核心是"入口 → 解析 → 打包 → 输出"，loader 处理单文件转换，plugin 贯穿全程扩展能力。面试常考：打包流程各阶段、loader 与 plugin 的位置、tree-shaking 时机。', 'Webpack,原理', 1, '审核通过', 'admin', 1, 'Mon Aug 24 2026 22:47:55 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (677, 2, 0, 1, 3, 1, '请简述 HTML 语义化标签的作用。', '', 0, 0, 'HTML 语义化标签的作用：1）提升可读性和可维护性——用 header、nav、main、article、section、aside、footer 等标签明确表达页面结构，开发者（尤其团队协作）一眼看懂内容区块的含义；2）利于 SEO——搜索引擎爬虫能更好地理解页面内容结构，标题层级（h1-h6）、语义标签会提升关键词权重和搜索排名；3）提升可访问性（无障碍）——屏幕阅读器等辅助技术能根据语义标签正确朗读和导航，方便视障用户；4）代码更规范、更清晰——相比满屏 div，语义标签让 HTML 结构自带"文档大纲"。常用语义标签：header（页头）、nav（导航）、main（主内容）、article（独立文章）、section（区块）、aside（侧边栏/补充）、footer（页脚）、figure/figcaption（配图）、time（时间）。注意：语义标签改变的是"含义"而非默认样式，仍可配合 CSS 自定义外观。面试常考：语义化好处、常用标签及适用场景、div 与语义标签取舍。', 'HTML,语义化', 1, '审核通过', 'admin', 1, 'Mon Aug 24 2026 22:47:55 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (678, 0, 0, NULL, 0, 1, '你好啊', '[{"code":"A","value":"撒地方"},{"code":"B","value":"啊士大夫"},{"code":"E","value":"阿斯蒂芬"}]', NULL, 1, '正确选项：A', '三百', 1, '审核通过', '请问', 4, 'Mon Aug 24 2026 23:00:20 GMT+0800 (中国标准时间)', 0, 'Wed Aug 26 2026 21:56:43 GMT+0800 (中国标准时间)', '请问');
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (679, 0, 0, NULL, 0, 1, '1', '[{"code":"A","value":"1"},{"code":"B","value":"1"},{"code":"C","value":"1"},{"code":"D","value":"1"}]', NULL, 1, '正确选项：A', '', 1, '审核通过', '小米', 2, 'Wed Aug 26 2026 22:18:28 GMT+0800 (中国标准时间)', 0, 'Wed Aug 26 2026 22:29:55 GMT+0800 (中国标准时间)', '小米');
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (680, 0, 0, 0, 0, 1, '在 JavaScript 中，typeof null 的结果是？', '[{"code":"A","value":"\\"null\\""},{"code":"B","value":"\\"object\\""},{"code":"C","value":"\\"undefined\\""},{"code":"D","value":"\\"number\\""}]', 0, 0, '正确选项：B', 'JS,基础', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (681, 0, 0, 0, 0, 0, '以下哪个不是 ES6 新增的语法特性？', '[{"code":"A","value":"箭头函数"},{"code":"B","value":"class 类"},{"code":"C","value":"var 声明"},{"code":"D","value":"解构赋值"}]', 0, 0, '正确选项：C', 'JS,ES6', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (682, 0, 0, 0, 1, 1, '以下属于 JavaScript 作用域类型的有哪些？', '[{"code":"A","value":"全局作用域"},{"code":"B","value":"函数作用域"},{"code":"C","value":"块级作用域"},{"code":"D","value":"类作用域"}]', 0, 0, '正确选项：ABC', 'JS,作用域', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (683, 0, 0, 0, 2, 1, '在 JavaScript 中，表达式 [] == false 的结果为 true。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'JS,类型转换', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (684, 0, 0, 0, 3, 1, '请简述 JavaScript 中闭包是什么，以及它的主要作用。', '', 0, 0, '闭包是指一个函数能够访问并记住其定义时所在词法作用域中变量的能力：即使外部函数已经执行完毕返回，这些变量依然被内部函数持有、不会被销毁。本质是函数定义时就确定了作用域链，内部函数沿链总能找到外层变量。主要作用：1）数据私有化/封装，外部无法直接访问和修改内部状态；2）延长变量生命周期，实现缓存与记忆化；3）实现高阶函数，如柯里化、防抖、节流、模块模式都依赖闭包。典型例子：function createCounter(){ let count=0; return ()=>++count; } 每次调用返回的函数都能访问并修改 count。注意：闭包会使被引用变量常驻内存，若持有大对象且长期不用会造成内存泄漏，应在不用时解除引用（置 null）。面试常追问：闭包形成条件、闭包与普通函数区别、内存泄漏如何避免。', 'JS,闭包', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (685, 0, 0, 0, 2, 1, 'Promise.all 只要其中任意一个 Promise 变为 rejected，整体就会立即 reject。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'JS,异步', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
