INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (688, 5, 0, 0, 2, 0, 'v-show 通过 display 控制元素显隐，v-if 通过创建或销毁 DOM 节点来控制。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'Vue,指令', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (689, 5, 0, 0, 3, 2, '请简述 Vue 3 的响应式原理。', '', 0, 0, 'Vue 3 的响应式基于 ES6 的 Proxy 实现，通过 new Proxy(target, handler) 代理整个对象，在 get 拦截器中做依赖收集（track），在 set、deleteProperty 等拦截器中触发更新（trigger）。工作流程：1）创建响应式对象时用 Proxy 包裹；2）组件渲染读取属性时，get 拦截把当前副作用（effect，即组件更新函数）收集为该属性的依赖；3）数据被修改时，set 拦截触发对应依赖执行，驱动视图更新。相比 Vue 2 的 Object.defineProperty 优势：1）能监听对象属性新增和删除，无需 Vue.set/Vue.delete；2）能直接监听数组下标和 length 变化，无需重写数组方法；3）支持 Map、Set 等新数据结构；4）是惰性代理，只有访问到属性才建立响应式，性能更好；5）对嵌套对象按需代理，避免 Vue2 递归遍历全部属性的初始化开销。ref 和 reactive 底层都基于 Proxy，ref 通过对象包裹基本类型后用 .value 访问。', 'Vue,响应式', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (690, 5, 0, 0, 0, 0, 'Vue 中用于监听响应式数据变化并执行副作用的选项是？', '[{"code":"A","value":"computed"},{"code":"B","value":"watch"},{"code":"C","value":"methods"},{"code":"D","value":"data"}]', 0, 0, '正确选项：B', 'Vue,监听', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (691, 4, 0, 0, 0, 1, 'React 中用于组件性能优化的 memo 函数属于？', '[{"code":"A","value":"内置函数（高阶组件）"},{"code":"B","value":"Hook"},{"code":"C","value":"生命周期方法"},{"code":"D","value":"事件处理器"}]', 0, 0, '正确选项：A', 'React,性能', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (692, 4, 0, 0, 2, 1, 'useEffect 的依赖数组为空时，回调函数只会在组件挂载后执行一次。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'React,Hooks', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (693, 4, 0, 0, 3, 1, '请简述 React 中受控组件与非受控组件的区别。', '', 0, 0, '受控组件与非受控组件是 React 管理表单元素的两类方式。受控组件：表单值由 React 的 state 统一管理，通过 value 绑定 state、onChange 更新 state，形成"数据驱动视图"的单向数据流。用户输入 → onChange → setState → 重渲染 → 显示新值。优点是值始终与 state 同步，便于实时校验、格式化（如金额转千分位）、多字段联动，数据来源单一可预测；缺点是每次输入都触发渲染、代码较繁琐。非受控组件：表单值由 DOM 自身维护，通过 ref 直接读取当前值（useRef），不经过 state。优点是代码简洁、性能开销小，适合提交时才取值、文件上传等一次性读取场景；缺点是无法在输入过程中实时校验和联动。官方推荐优先使用受控组件以保证数据可控；仅当确实不需要监听变化时才用非受控组件，并可用 defaultValue 设初始值。面试常追问：为什么推荐受控、非受控组件如何取值。', 'React,表单', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (694, 4, 0, 0, 1, 1, '以下属于 React 常见 Hook 的有哪些？', '[{"code":"A","value":"useState"},{"code":"B","value":"useEffect"},{"code":"C","value":"useRef"},{"code":"D","value":"useAsync"}]', 0, 0, '正确选项：ABC', 'React,Hooks', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (695, 8, 0, 0, 0, 1, 'TypeScript 中定义联合类型使用哪个符号？', '[{"code":"A","value":"&"},{"code":"B","value":"|"},{"code":"C","value":"?"},{"code":"D","value":"!"}]', 0, 0, '正确选项：B', 'TS,类型', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (696, 8, 0, 0, 2, 0, 'interface 可以通过 extends 关键字继承另一个 interface。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'TS,接口', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (697, 8, 0, 0, 3, 1, '请简述 TypeScript 中 type 与 interface 的主要区别。', '', 0, 0, 'type 和 interface 都能定义类型，但各有侧重。interface 特点：1）可被 extends 继承，支持接口继承、类实现；2）支持声明合并——同名 interface 自动合并，便于扩展第三方库类型；3）主要描述对象、函数、类的结构形状。type 特点：1）更灵活，除了对象还能定义联合类型（string|number）、交叉类型（A&B）、元组、字面量类型、基本类型别名；2）不能重复声明同名 type；3）支持 typeof/instanceof 推断、映射类型等高级技巧。选择建议：描述对象结构、需要继承或声明合并时用 interface；需要定义联合/交叉/元组等组合类型时用 type；两者可混合使用（interface 的属性类型可用 type 定义）。一个常考点：interface 无法定义联合类型，type 可以，所以"类型别名"与"接口"能力不完全相同。', 'TS,类型', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (698, 8, 0, 0, 0, 2, '关于 TypeScript 中 any 与 unknown 的区别，下列说法正确的是？', '[{"code":"A","value":"两者完全相同，可随意替换"},{"code":"B","value":"unknown 更安全，使用前必须进行类型收窄（断言或判断）"},{"code":"C","value":"any 比 unknown 更安全"},{"code":"D","value":"unknown 不能接收任意类型的值"}]', 0, 0, '正确选项：B', 'TS,类型', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (699, 10, 0, 0, 0, 1, 'HTTP 状态码 304 表示什么含义？', '[{"code":"A","value":"服务器内部错误"},{"code":"B","value":"永久重定向"},{"code":"C","value":"未修改，可直接使用本地缓存"},{"code":"D","value":"请求参数错误"}]', 0, 0, '正确选项：C', 'HTTP,状态码', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (700, 10, 0, 2, 2, 0, 'HTTP 协议默认端口是 80，HTTPS 默认端口是 443。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'HTTP,基础', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (701, 10, 0, 0, 3, 0, '请简述 HTTP 与 HTTPS 的主要区别。', '', 0, 0, 'HTTP 与 HTTPS 的核心区别在于安全性。1）加密：HTTP 明文传输，数据可被窃听；HTTPS 在 HTTP 之下增加 SSL/TLS 加密层，对传输内容加密，即使被截获也无法直接读取。2）身份认证：HTTPS 需向 CA 申请数字证书，用于验证服务器身份、防止中间人伪装；HTTP 没有身份校验。3）完整性：HTTPS 通过消息摘要/签名校验数据在传输中是否被篡改。4）端口：HTTP 默认 80，HTTPS 默认 443。5）性能：HTTPS 因握手和加解密多些开销，但 TLS 1.3、会话复用已使其接近 HTTP 性能。原理：采用"非对称加密协商密钥 + 对称加密传输数据"——握手阶段用非对称加密（RSA/ECDHE）协商出会话密钥，之后用对称加密（AES）高效传输，兼顾安全与速度。浏览器地址栏的锁图标表示 HTTPS 生效。', 'HTTP,HTTPS', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (702, 10, 0, 0, 1, 0, '以下属于 HTTP 请求方法的有哪些？', '[{"code":"A","value":"GET"},{"code":"B","value":"POST"},{"code":"C","value":"DELETE"},{"code":"D","value":"FETCH"}]', 0, 0, '正确选项：ABC', 'HTTP,方法', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (703, 11, 0, 1, 3, 2, '请简述浏览器从输入 URL 到页面渲染完成的主要过程。', '', 0, 0, '从输入 URL 到页面渲染完成，分为网络与渲染两大阶段。网络阶段：1）DNS 解析域名得到 IP（先查缓存、hosts，再查 DNS 服务器）；2）TCP 三次握手建立连接（HTTPS 还需 TLS 握手协商密钥）；3）发送 HTTP 请求并接收响应；4）判断缓存：强缓存命中直接读本地，协商缓存发请求比对，304 则用本地。渲染阶段：5）解析 HTML 构建 DOM 树，解析 CSS 构建 CSSOM 树；6）DOM 与 CSSOM 合成渲染树（过滤 display:none 等不可见节点）；7）布局 Layout/回流，计算节点几何位置大小；8）绘制 Paint 输出像素；9）合成 Composite，GPU 分层合成显示到屏幕。关键点：JS 会阻塞 DOM 解析（可用 defer/async 或放 body 底部），CSS 会阻塞渲染（CSSOM 未完成不渲染）。面试常追问：DOMContentLoaded 与 load 区别、回流重绘优化。', '浏览器,渲染', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (704, 11, 0, 1, 0, 1, '关于 localStorage 与 sessionStorage 的区别，下列说法正确的是？', '[{"code":"A","value":"两者没有区别"},{"code":"B","value":"localStorage 持久保存，sessionStorage 关闭标签页后清除"},{"code":"C","value":"localStorage 仅会话有效，sessionStorage 持久保存"},{"code":"D","value":"两者都只能存储对象类型"}]', 0, 0, '正确选项：B', '浏览器,存储', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (705, 1, 0, 1, 0, 0, '以下哪些 CSS 方案可以实现元素的水平垂直居中？', '[{"code":"A","value":"flex 布局（justify-content + align-items）"},{"code":"B","value":"position 定位 + transform 平移"},{"code":"C","value":"grid 布局"},{"code":"D","value":"以上都可以"}]', 0, 0, '正确选项：D', 'CSS,布局', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (706, 2, 0, 1, 2, 0, 'HTML5 新增了 header、nav、main、footer 等语义化标签。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'HTML,语义化', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (707, 9, 0, 0, 3, 1, '请简述 git merge 与 git rebase 的区别。', '', 0, 0, 'git merge 与 git rebase 都是整合分支的方式，区别在于提交历史的组织方式。merge：把目标分支的提交合并到当前分支，会生成一个额外的合并提交（merge commit），保留两个分支完整历史，分叉清晰可见。优点是安全、不改写历史，适合公共分支协作；缺点是历史可能出现多条交叉线，不够线性整洁。rebase：把当前分支的提交"摘下"后依次重新应用到目标分支顶端，使历史变成一条直线。优点是历史线性干净、便于追溯和 review；缺点是会改写提交历史（提交哈希变化），如果该分支已被多人共享，会导致他人本地与远端不一致甚至冲突。使用建议：个人本地分支用 rebase 保持整洁；多人共享分支（main/develop）用 merge 避免改写公共历史。冲突处理：git rebase --abort 放弃 / --continue 解决后继续。', 'Git,分支', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (708, 6, 0, 0, 0, 1, 'Node.js 处理高并发异步 I/O 的核心机制是？', '[{"code":"A","value":"多线程"},{"code":"B","value":"事件循环 + 非阻塞 I/O"},{"code":"C","value":"协程抢占式调度"},{"code":"D","value":"多进程共享内存"}]', 0, 0, '正确选项：B', 'Node,异步', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (709, 7, 0, 0, 3, 1, '请简述 Webpack 中 loader 与 plugin 的区别。', '', 0, 0, 'loader 与 plugin 是 Webpack 的两大扩展机制，职责完全不同。loader：处理模块源代码的转换，是"文件级"处理。Webpack 本身只能识别 JS，loader 负责把各种非 JS 资源（CSS、Less、图片、字体、TS、Vue 文件等）转换成 Webpack 能处理的模块，本质是一个转换函数，在模块加载/编译阶段执行，可链式调用（从右到左，如 style-loader→css-loader→sass-loader）。典型：babel-loader 转译 ES6+、css-loader 解析 CSS、vue-loader 解析 .vue。plugin：扩展 Webpack 整个打包流程能力，是"构建级"处理，可在打包生命周期钩子上做复杂操作：代码压缩（TerserPlugin）、生成 HTML（HtmlWebpackPlugin）、提取 CSS（MiniCssExtractPlugin）、环境变量注入（DefinePlugin）、模块分包（SplitChunksPlugin）等。一句话区分：loader 在打包输入阶段转换单个文件，plugin 在打包全过程增强功能。', 'Webpack,原理', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:22:57 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (710, 0, 0, 0, 3, 1, 'JavaScript 中有哪些数据类型？', '', 0, 0, 'JavaScript 数据类型分为原始类型和引用类型。原始类型 7 种：string、number、boolean、null、undefined、symbol（ES6，唯一标识）、bigint（ES2020，大整数）。引用类型：object，包括普通对象、数组、函数、Date、RegExp、Map、Set 等。关键区别：1）存储：原始类型按值存储于栈，赋值是值拷贝；引用类型栈存地址、堆存数据，赋值是引用拷贝（多个变量指向同一对象）。2）比较：原始类型比值，引用类型比引用地址。3）检测：typeof 能判断基本类型（typeof null 返回 "object" 是历史 bug），判断数组/对象需用 Object.prototype.toString.call() 或 Array.isArray/instanceof。面试常考：为什么 typeof null 是 object、如何准确判断类型、深浅拷贝区别。', 'JS,基础', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (711, 0, 0, 1, 3, 1, 'null 和 undefined 有什么区别？', '', 0, 0, 'null 和 undefined 都表示"空"，但语义和产生场景不同。undefined 表示"变量已声明但未赋值"，是系统默认值。产生场景：声明变量未赋值、函数没有 return（返回 undefined）、访问对象不存在的属性、函数参数未传时形参为 undefined。null 表示"空值/空对象"，是开发者主动赋的值，表示"这里有一个值但是空的"。典型用法：手动清空变量引用（a=null）、对象类型可能返回空时的占位。比较：两者 == 相等（都转成 false），=== 不相等（类型不同）。typeof undefined 返回 "undefined"，typeof null 返回 "object"（历史遗留 bug）。面试常考：为什么 typeof null 是 object、何时用 null 何时用 undefined。', 'JS,基础', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (712, 0, 0, 3, 3, 0, '== 和 === 有什么区别？', '', 0, 0, '== 与 === 的区别在于是否进行类型转换。==（宽松相等）：比较前做隐式类型转换，把两个操作数转成相同类型再比。例如 1=="1" 为 true、null==undefined 为 true、[]==false 为 true、0=="" 为 true。===（严格相等）：不转换类型，类型和值都相同才返回 true，如 1==="1" 为 false、null===undefined 为 false。补充：=== 对 NaN 也不成立（NaN===NaN 为 false），判断 NaN 用 Number.isNaN；+0===-0 为 true。推荐业务代码一律用 ===，避免隐式转换带来难以排查的 bug；确实需要宽松比较时要清楚其转换规则（ToPrimitive）。面试常考：== 的转换规则、若干经典陷阱表达式的结果。', 'JS,基础', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (713, 0, 0, 2, 2, 1, 'typeof null 的结果是 "object"，这是 JavaScript 的历史遗留 bug。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'JS,基础', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (714, 0, 0, 0, 3, 1, 'isNaN 和 Number.isNaN 有什么区别？', '', 0, 0, 'isNaN 与 Number.isNaN 都能判断 NaN，但行为本质不同。isNaN（全局函数）：会先把参数强制转换为数字再判断，所以 isNaN("abc") 返回 true（"abc" 转数字失败得 NaN），isNaN("123") 返回 false（"123" 能转成 123）。它判断的是"转换后是否为 NaN"。Number.isNaN（ES6 新增）：不做类型转换，只有参数本身就是 NaN（类型是 number 且值为 NaN）才返回 true，所以 Number.isNaN("abc") 为 false、Number.isNaN(NaN) 为 true。记忆：isNaN 宽松、Number.isNaN 严格。开发中推荐用 Number.isNaN，因为 isNaN 对非数字字符串会误判为 true，语义不准确。面试常考：isNaN("123") 为什么是 false、如何准确判断 NaN。', 'JS,Number', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (715, 0, 0, 0, 3, 1, 'let、const 和 var 的区别是什么？', '', 0, 0, 'let、const、var 的区别集中在作用域、提升和可变性。var：1）函数作用域，无块级作用域（{} 内声明外部可访问）；2）有变量提升（声明提升到作用域顶部但值为 undefined），声明前可用；3）可重复声明；4）会挂到 window 全局。let：1）块级作用域；2）无提升（存在暂时性死区 TDZ，声明前访问报错）；3）不可重复声明；4）不挂 window。const：与 let 相同（块级作用域、TDZ、不可重复声明），额外要求：1）声明时必须初始化；2）不可重新赋值（引用指向不可改，但对象内部属性可变）。使用建议：默认用 const，需要重新赋值用 let，尽量避免 var。面试常考：变量提升的具体表现、暂时性死区、const 声明的对象为何能改属性。', 'JS,ES6', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (716, 0, 0, 0, 2, 1, 'let/const 声明的变量在其声明语句之前访问会报错，这个区域称为暂时性死区（TDZ）。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'JS,ES6', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (717, 0, 0, 1, 3, 1, '箭头函数和普通函数有什么区别？', '', 0, 0, '箭头函数是 ES6 的简写函数，与普通函数有多个本质区别。1）this 指向：箭头函数没有自己的 this，继承定义时所在外层作用域（词法作用域），且无法被 call/apply/bind 改变；普通函数 this 由调用方式决定。2）构造函数：箭头函数没有 prototype、不能 new；普通函数可以。3）arguments：箭头函数没有自己的 arguments，需用剩余参数 ...args 代替；普通函数有。4）new.target：箭头函数没有。5）语法：箭头函数可省略 function，单表达式可省略 return 和花括号，更简洁。典型场景：箭头函数适合回调、定时器、数组方法（map/filter）中需要保持外层 this 的场景；对象方法、需要动态 this、需要 arguments 或作为构造函数时应使用普通函数。面试常考：对象方法里箭头函数的 this、箭头函数能否 bind。', 'JS,函数', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (718, 0, 0, 1, 2, 1, '箭头函数的 this 在函数定义时确定，普通函数的 this 在函数调用时确定。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'JS,函数', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (719, 0, 0, 1, 3, 1, 'call、apply 和 bind 有什么区别？', '', 0, 0, 'call、apply、bind 都是 Function.prototype 上用于显式改变 this 指向的方法，区别在调用方式和参数。call：立即执行，参数逐个传入，fn.call(thisArg, arg1, arg2)。apply：立即执行，参数以数组传入，fn.apply(thisArg, [arg1, arg2])，适合参数数量不固定或已有数组的场景（如 Math.max.apply(null, arr)）。bind：不立即执行，返回一个绑定 this（且可预设参数）的新函数，之后可随时调用，fn.bind(thisArg, arg1)(...)，常用于事件回调、React 类组件中传递方法。共同点：第一个参数都是 this 指向，传 null/undefined 时非严格模式指向全局。面试常考：手写三者实现、bind 返回的函数能否被 new、apply 与 call 的传参差异。', 'JS,this', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (720, 0, 0, 0, 3, 1, 'JavaScript 中 this 的绑定规则有哪些？', '', 0, 0, 'JavaScript 中 this 的指向在函数调用时确定，遵循四种绑定规则（优先级从高到低）：1）new 绑定（最高）：通过 new 调用构造函数时 this 指向新建实例。2）显式绑定：通过 call/apply/bind 明确指定 this。3）隐式绑定：函数作为对象方法被调用时 this 指向调用它的对象（"谁调用指向谁"）；注意把方法取出来单独调用（const f=obj.method; f()）会丢失 this。4）默认绑定：以上都不满足时，非严格模式 this 指向全局（浏览器 window），严格模式为 undefined。特殊情况：箭头函数没有自己的 this，继承定义时外层作用域的 this，以上规则不适用（也不能用 call/apply/bind 改变）。面试常考：取方法后调用 this 丢失、事件回调中 this、箭头函数与 this 的结合。', 'JS,this', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (721, 0, 0, 2, 3, 1, '什么是柯里化（currying）？', '', 0, 0, '柯里化（Currying）是把一个接收多个参数的函数，转换成一系列只接收一个参数的函数的过程，支持逐个参数调用和部分应用。原理：利用闭包保存已传入的参数，当参数收集齐全时再一次性执行原函数。示例：function add(a,b){return a+b} 柯里化后 const curriedAdd = a => b => a+b，curriedAdd(2)(3) 等于 5。通用实现：function curry(fn){ return function curried(...args){ if(args.length>=fn.length) return fn(...args); return (...rest)=>curried(...args,...rest); }; } 作用：1）参数复用/预设，提前固定某些参数生成专用函数；2）延迟执行，参数没给够时不执行；3）便于函数组合（compose/pipe）；4）提升函数复用灵活性。面试常考：手写 curry、柯里化与偏函数（partial）的区别。', 'JS,函数', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (722, 0, 0, 1, 3, 1, '什么是闭包？它有什么作用？', '', 0, 0, '闭包是指一个函数能够访问并记住其定义时所在作用域的变量，即使外层函数已执行完毕，这些变量依然被内部函数持有、不会销毁。本质是函数定义时就确定了作用域链，内部函数沿作用域链总能找到外层变量。常见作用：1）数据私有化/封装，把状态藏在函数内部，如计数器、模块模式；2）延长变量生命周期，实现缓存、记忆化；3）实现高阶函数，防抖、节流、柯里化等依赖闭包；4）模块化，IIFE 配合闭包实现单例和私有方法。示例：function createCounter(){ let n=0; return ()=>++n; } 缺点：闭包引用的变量常驻内存，若引用大对象且长期不用会造成内存泄漏，需及时解除引用（置 null）。面试常考：闭包形成条件、闭包变量如何被修改、内存泄漏。', 'JS,闭包', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (723, 0, 0, 0, 3, 2, '闭包导致内存泄漏的场景有哪些？如何避免？', '', 0, 0, '闭包导致内存泄漏的根源：闭包长期持有外部函数变量，导致这些变量无法被 GC 回收，即使业务上已不再需要。常见场景：1）闭包引用大型数组/对象但从未使用；2）事件监听器绑定了引用大对象的回调且从未移除；3）定时器/interval 的回调持有大对象且未清除；4）全局变量上挂着闭包函数。示例：function createLeak(){ const big=new Array(1000000); return ()=>console.log("leak"); } 只要返回的匿名函数还被引用，big 就无法回收。避免方法：1）不需要时把引用置 null（let fn=createLeak(); fn=null;）；2）用 WeakMap/WeakSet 持有对象引用（弱引用不阻止 GC）；3）组件销毁时清除定时器、解绑事件监听（Vue onUnmounted、React useEffect 清理函数）；4）用 Chrome DevTools Memory 抓堆快照前后对比定位泄漏。面试常考：如何定位泄漏、WeakMap 为何能避免泄漏。', 'JS,闭包', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (724, 0, 0, 0, 3, 1, '什么是原型和原型链？', '', 0, 0, '原型和原型链是 JavaScript 实现继承的机制。原型（prototype）：每个函数都有一个 prototype 属性指向原型对象，通过该函数 new 出来的实例通过 __proto__ 指向该原型，从而能访问原型上定义的方法和属性。原型链（prototype chain）：每个对象都有 __proto__（Object.create(null) 创建的除外），__proto__ 指向其构造函数的 prototype，而 prototype 自身又是对象又有自己的 __proto__，层层向上串联，最终到 Object.prototype.__proto__（即 null）。访问对象属性时沿这条链逐级查找，找到即返回，找不到返回 undefined。示例：function Person(){} Person.prototype.sayHi=function(){}; const p=new Person(); p.sayHi() —— p 上没有 sayHi，沿 __proto__ 找到 Person.prototype 上的方法。作用：属性共享减少内存、方法继承、instanceof 判断。面试常考：原型链终点、实例/构造函数的三角关系、hasOwnProperty 与原型属性、手写继承。', 'JS,原型', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (725, 0, 0, 1, 3, 2, '解释 JavaScript 原型链机制，并说明 instanceof 如何实现。', '', 0, 0, '原型链本质：对象通过 __proto__ 逐级向上查找属性，直到 Object.prototype 的 __proto__（null）。instanceof 原理：沿着对象的原型链查找，是否存在某个原型等于构造函数的 prototype。手写实现：function myInstanceof(obj,C){ if(obj==null || (typeof obj!=="object" && typeof obj!=="function")) return false; let proto=Object.getPrototypeOf(obj); const target=C.prototype; while(proto){ if(proto===target) return true; proto=Object.getPrototypeOf(proto);} return false; } 注意：1）instanceof 只能判断对象与构造函数的关系，基本类型需用 typeof；2）跨 realm（如 iframe）时 Object.prototype 不同会导致 instanceof 失效，可用 Object.prototype.toString.call 或 Symbol.hasInstance；3）修改构造函数 prototype 指向会影响 instanceof 结果。延伸：Object.create(null) 创建的对象没有原型链；Function.__proto__ === Function.prototype 说明函数自身也是对象。', 'JS,原型', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (726, 0, 0, 1, 3, 1, 'new 操作符做了什么？', '', 0, 0, 'new 操作符用于创建构造函数的实例，内部做四件事：1）创建一个新的空对象 obj；2）把 obj 的 __proto__ 指向构造函数的 prototype，让实例能访问原型上的方法和属性（建立原型链）；3）以 obj 作为 this 执行构造函数，把 this.xxx 赋值到新对象上；4）处理返回值：如果构造函数显式返回了一个对象，则返回该对象，否则返回新建的 obj。手写实现：function myNew(Ctor,...args){ const obj=Object.create(Ctor.prototype); const res=Ctor.apply(obj,args); return (res!==null && typeof res==="object")?res:obj; } 关键点：只有返回的是对象（或函数）才会覆盖，返回基本类型（数字、字符串）会被忽略，仍返回 obj。箭头函数没有 prototype，不能作为构造函数用 new 调用。面试常考：new 的返回值规则、手写 myNew。', 'JS,面向对象', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (727, 0, 0, 2, 3, 1, '什么是深拷贝与浅拷贝？', '', 0, 0, '深拷贝与浅拷贝的区别在于对嵌套对象的复制深度。浅拷贝：只复制对象第一层属性，若属性值是引用类型（对象/数组），复制的是引用地址，新旧对象共享该嵌套对象，修改会互相影响。常见方式：Object.assign({},obj)、展开运算符 {...obj}、数组 slice/concat。深拷贝：递归复制所有层级，得到完全独立的新对象，修改互不影响。实现：1）JSON.parse(JSON.stringify(obj))——简单但有缺陷：丢失函数、undefined、Symbol，RegExp/Date 会被转成字符串或对象，无法处理循环引用；2）structuredClone()——浏览器原生，可处理 Date、Map、Set 等；3）手写递归深拷贝——用 WeakMap 记录已拷贝对象以处理循环引用，并对数组、Date、RegExp 分别处理。面试常考：JSON 深拷贝的缺陷、手写深拷贝处理循环引用。', 'JS,基础', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (728, 0, 0, 1, 3, 1, 'Set 和 Map 有什么区别？', '', 0, 0, 'Set 和 Map 都是 ES6 新增的数据结构。Set：值的集合，元素唯一（自动去重），适合数组去重（[...new Set(arr)]）。提供 add、delete、has、size、clear 方法，可遍历，常用于去重、交集/并集/差集运算。Map：键值对的集合，键可以是任意类型（包括对象、函数），突破了普通对象键只能是字符串（或 Symbol）的限制。提供 set、get、has、delete、size、clear 方法，可遍历，键值对保持插入顺序。与普通对象对比：Map 键有序、可遍历、键类型任意；普通对象键只能字符串/Symbol，遍历顺序与可枚举性较复杂。选择：需要唯一性判断用 Set；需要复杂类型做键或用频繁增删查的键值对用 Map。面试常考：Map 与 Object 区别、Set 如何实现交集并集、WeakMap 与 Map 区别。', 'JS,ES6', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (729, 0, 0, 1, 2, 1, 'WeakMap 的键必须是对象，且键为弱引用、不影响垃圾回收。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'JS,ES6', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (730, 0, 0, 3, 3, 1, 'WeakMap 与 Map 的核心区别是什么？', '', 0, 0, 'WeakMap 与 Map 的核心区别在于弱引用和键的约束。1）键类型：WeakMap 的键只能是对象（或函数），不能是基本类型；Map 的键可以是任意值。2）引用强度：WeakMap 对键是弱引用，即若没有其他强引用指向该键对象，该对象可被垃圾回收（即使它仍在 WeakMap 中）；Map 是强引用，会阻止键对象被回收。3）可枚举性：WeakMap 没有 size、不可遍历（无 keys/values/entries/forEach），因为键随时可能被 GC 回收无法稳定遍历；Map 可遍历。4）方法：WeakMap 只有 get/set/has/delete；Map 还有 size、clear、遍历方法。使用场景：WeakMap 常用于给对象关联私有数据、缓存 DOM 节点相关数据（DOM 移除时自动释放）、Vue 的响应式依赖收集；Map 用于常规键值存储、需要遍历的场景。面试常考：为什么 WeakMap 不可遍历、WeakMap 如何避免内存泄漏。', 'JS,ES6', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (731, 0, 0, 1, 2, 1, 'Symbol 是唯一的标识符，可以作为对象属性名以避免属性名冲突。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'JS,ES6', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (732, 0, 0, 0, 3, 1, '什么是 BigInt？', '', 0, 0, 'BigInt 是 ES2020 引入的第七种原始类型，用于表示超出 Number 安全范围（超过 Number.MAX_SAFE_INTEGER，即 2^53-1）的整数。定义方式：整数后加 n 后缀，如 9007199254740993n；或用 BigInt() 转换，如 BigInt("123")。特点：1）可精确表示任意大的整数，不受浮点数精度限制；2）不能与 Number 直接混合运算（1n+1 会报错），需显式转换；3）与 Number 用 == 比较时相等（1n==1 为 true），但 === 不等（类型不同）；4）不能传给 Math 方法；5）JSON.stringify 无法序列化 BigInt（会抛错）。适用场景：大整数运算、ID 超过安全整数、金融/加密场景。面试常考：Number 精度丢失原因、BigInt 与 Number 的运算规则。', 'JS,ES6', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (733, 0, 0, 0, 3, 1, '什么是 Proxy？它有什么用途？', '', 0, 0, 'Proxy 是 ES6 提供的内置对象，用于创建对象的代理，从而拦截并自定义对象上的基本操作。基本用法：new Proxy(target, handler)，handler 中定义拦截器（trap），如 get（读取）、set（设置）、deleteProperty（删除）、has（in 操作符）、apply（函数调用）、construct（new 调用）等。特点：1）拦截范围广，覆盖对象几乎所有操作；2）set 拦截器返回布尔值决定是否允许修改；3）配合 Reflect 使用更规范，Reflect.get/set 与 Proxy 一一对应且语义统一。主要用途：1）数据绑定和响应式系统（Vue 3 基于 Proxy）；2）表单校验、权限控制（拦截 set 校验非法值）；3）访问日志/埋点（拦截 get 统计）；4）实现隐藏私有属性、只读对象。相比 Object.defineProperty：Proxy 能监听属性新增、删除、数组索引等，能力更强。面试常考：Proxy 的 trap 有哪些、与 Reflect 的关系。', 'JS,Proxy', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (734, 0, 0, 0, 2, 1, 'Proxy 能监听对象属性的新增和删除，而 Object.defineProperty 只能监听已存在的属性。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'JS,Proxy', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (735, 0, 0, 0, 3, 1, '什么是 Promise？', '', 0, 0, 'Promise 是 ES6 引入的异步编程解决方案，用于解决回调地狱问题。核心概念：Promise 表示一个异步操作的最终完成或失败及其结果值，有三种状态：pending（进行中）、fulfilled（已成功）、rejected（已失败）；状态一旦从 pending 变为 fulfilled/rejected 就不可再改变（单向、不可逆）。基本用法：new Promise((resolve,reject)=>{ 异步操作成功调用 resolve(value)，失败调用 reject(reason) })。通过 then 处理成功、catch 处理失败、finally 无论结果都执行；then 返回新 Promise，支持链式调用。常用静态方法：Promise.all（全部成功才成功，任一失败整体失败）、Promise.race（谁先完成返回谁）、Promise.allSettled（全部结束，各自返回状态和结果）、Promise.resolve/reject。优点：链式调用避免回调地狱、状态不可变结果可靠、配合 async/await 可像同步代码一样书写。面试常考：Promise 状态、链式错误捕获、all 与 allSettled 区别、手写简易 Promise。', 'JS,异步', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (736, 0, 0, 0, 3, 1, 'async/await 的原理是什么？', '', 0, 0, 'async/await 是 ES2017 引入的异步语法糖，本质是 Promise 的封装，让异步代码写起来像同步代码。async 函数：声明一个返回 Promise 的函数，内部 return 的值会被自动包装成已 resolved 的 Promise；若函数内抛出异常，则返回 rejected 的 Promise。await 关键字：只能在 async 函数内使用，会暂停当前函数执行，等待右侧 Promise 进入 settled 状态后再继续；若 Promise 被 reject，await 会抛出异常，可用 try/catch 捕获。底层原理：async/await 可理解为 Generator + 自动执行器（co）的语法糖——async 函数编译后等价于 generator，await 对应 yield，编译器自动一步步推进执行。优点：1）代码接近同步写法可读性强；2）错误处理用 try/catch 更直观；3）可方便地串行/并行控制（结合 Promise.all）。面试常考：await 到底等什么（非 Promise 值也会被包装）、for 循环中 await 的顺序、并发如何不阻塞。', 'JS,异步', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (737, 0, 0, 0, 3, 2, '解释 JavaScript 的事件循环（Event Loop）机制。', '', 0, 0, 'JavaScript 是单线程语言，事件循环（Event Loop）是它实现异步非阻塞的核心机制，用于协调同步代码、微任务和宏任务的执行顺序。执行流程：1）执行同步代码（当前宏任务，即 script）；2）执行结束后清空整个微任务队列（Promise.then/catch、queueMicrotask、MutationObserver、async/await 后续）；3）从宏任务队列取出一个宏任务（setTimeout、setInterval、I/O、DOM 事件、AJAX 回调）执行；4）再清空所有微任务；5）循环往复，浏览器还会在合适时机执行渲染。关键规则：每个宏任务执行完后，必须把当前所有微任务执行完才进入下一个宏任务，微任务优先级高于宏任务。典型例题：console.log(1); setTimeout(()=>console.log(2),0); Promise.resolve().then(()=>console.log(3)); console.log(4); 输出为 1→4→3→2，因为 Promise.then 是微任务先于 setTimeout 宏任务。面试常考：宏任务/微任务列表、async/await 在事件循环中的位置、Node 与浏览器差异。', 'JS,事件循环', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (738, 0, 0, 0, 2, 1, '事件循环中，微任务（如 Promise.then）优先于宏任务（如 setTimeout）执行。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'JS,事件循环', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (739, 0, 0, 0, 2, 2, '执行 console.log(1); setTimeout(()=>console.log(2),0); Promise.resolve().then(()=>console.log(3)); console.log(4); 输出顺序为 1 → 4 → 3 → 2。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'JS,事件循环', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (740, 0, 0, 1, 3, 1, '什么是防抖（debounce）和节流（throttle）？', '', 0, 0, '防抖（debounce）和节流（throttle）都是限制函数执行频率的性能优化手段。防抖：事件连续触发时，只在最后一次触发后的延迟时间内没有再次触发才执行一次，即"停止触发后 n 秒执行"，把多次触发合并成一次。适用于搜索框输入（等用户停止输入再请求）、窗口 resize、按钮提交。实现：function debounce(fn,delay){ let t; return function(...args){ clearTimeout(t); t=setTimeout(()=>fn.apply(this,args),delay); }; } 节流：在固定时间间隔内最多执行一次，无论触发多少次，即"n 秒内只执行一次"。适用于滚动监听、鼠标移动、拖拽、高频点击。实现：function throttle(fn,delay){ let last=0; return function(...args){ const now=Date.now(); if(now-last>=delay){ last=now; fn.apply(this,args);} }; } 区别总结：防抖关注"停止后执行"，节流关注"限频执行"。面试常考：手写防抖节流（含立即执行版）、两者适用场景、leading/trailing 参数。', 'JS,性能', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (741, 0, 0, 1, 3, 1, 'JS 为什么是单线程的？', '', 0, 0, 'JavaScript 被设计为单线程语言，根本原因是浏览器环境需求。JS 的主要职责是操作 DOM、响应用户交互，如果 JS 是多线程，两个线程同时修改同一个 DOM 节点，浏览器无法确定以谁为准，会导致界面状态不一致和渲染错乱。为保证操作一致性和简单性，JS 采用单线程模型——同一时间只执行一段代码。如何实现异步非阻塞：虽是单线程，但通过事件循环（Event Loop）+ 任务队列，把耗时操作（定时器、网络请求、I/O）交给浏览器其他线程（网络线程、定时器线程）处理，完成后把回调推入任务队列，主线程空闲时再取出执行，从而实现不阻塞主线程的异步效果。补充：单线程也有风险——一段 JS 死循环或执行过久会阻塞页面（白屏/卡死），所以大计算应拆成异步任务或交给 Web Worker（独立线程，不能操作 DOM）。面试常考：为什么不用多线程、事件循环如何配合、Web Worker 适用场景。', 'JS,基础', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (742, 0, 0, 2, 3, 2, '什么是内存泄漏？常见的泄漏场景有哪些？', '', 0, 0, '内存泄漏是指程序中已不再使用的内存没有被及时释放，导致内存占用持续增长，最终可能造成页面卡顿甚至崩溃。JS 内存泄漏常见场景：1）全局变量滥用——未用 var/let/const 声明的变量挂在 window 上一直存在；2）定时器未清除——setInterval/setTimeout 回调持有大对象且不清理；3）事件监听未解绑——DOM 元素被移除但监听器还挂着；4）闭包长期持有外部大对象；5）DOM 引用未释放——变量还存着已删除的 DOM 节点引用。如何定位：Chrome DevTools Memory 面板抓取 Heap Snapshot 前后对比，观察哪些对象占用内存未释放；也可用 performance.memory 监控堆大小。如何避免：及时 clearInterval/clearTimeout；组件销毁时移除事件监听（Vue onUnmounted、React useEffect 清理函数）；不用的大对象置 null；用 WeakMap/WeakSet 存引用。面试常考：说出几种泄漏场景、如何用 DevTools 排查。', 'JS,内存', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (743, 0, 0, 1, 3, 1, 'Object.defineProperty 与 Proxy 在响应式实现上有何差异（为什么 Vue3 改用 Proxy）？', '', 0, 0, '两者都是实现响应式/数据拦截的技术，Vue 2 用 Object.defineProperty，Vue 3 改用 Proxy。Object.defineProperty（Vue 2）：通过定义属性的 getter/setter 劫持读写。局限性：1）只能劫持对象已存在的属性，新增/删除属性监听不到（需 Vue.set/Vue.delete 补丁）；2）无法监听数组下标修改和 length 变化（需重写 7 个数组方法）；3）需要递归遍历对象所有属性一次性完成劫持，初始化开销大。Proxy（Vue 3）：直接代理整个对象，拦截 get/set/deleteProperty/has 等所有操作。优势：1）能监听属性新增、删除、数组下标、length 变化；2）支持 Map、Set 等新数据结构；3）是惰性代理，只有访问到属性才建立响应式，性能更好；4）无需重写数组方法。结论：Proxy 能力更强、性能更好、实现更简洁，是 Vue 3 响应式重构的核心原因。面试常考：两者差异、Vue 2 为何重写数组方法、Proxy 的惰性。', 'JS,Proxy', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (744, 11, 0, 0, 3, 1, '什么是事件冒泡和事件捕获？', '', 0, 0, '事件冒泡和事件捕获是浏览器事件传播的两个阶段，共同构成事件流。事件传播顺序（从 window 出发）：捕获阶段（window→document→...→目标元素祖先→目标元素）→ 目标阶段 → 冒泡阶段（目标元素→祖先→...→document→window）。捕获阶段：事件从最外层 window 逐层向下传播到目标元素，addEventListener 第三个参数为 true 时在捕获阶段触发。冒泡阶段：事件从目标元素逐层向上冒泡回 window，默认事件处理在冒泡阶段执行（第三个参数默认 false 表示冒泡阶段）。作用：冒泡是事件委托的基础（父元素能收到子元素冒泡上来的事件）；捕获常用于在到达目标前拦截事件。面试常考：如何阻止冒泡（stopPropagation）、stopImmediatePropagation 区别、事件流顺序。', '浏览器,事件', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (745, 11, 0, 0, 3, 1, '什么是事件委托？有什么好处？', '', 0, 0, '事件委托（事件代理）是利用事件冒泡机制，把多个子元素的事件监听统一绑定到共同父元素上，通过事件对象的 target 属性判断实际触发的是哪个子元素，再执行相应逻辑。原理：子元素触发的事件会冒泡到父元素，父元素只需一个监听器就能捕获所有子元素的事件。优点：1）减少监听器数量、节省内存（成千上万个 li 不用每个都绑定）；2）动态元素友好，后续新增的子元素无需重新绑定事件；3）统一管理代码更简洁。示例：ul 上绑定 click，通过 e.target.closest("li") 判断点击的是哪个 li 并读取 data 属性。注意：1）需用 e.target 判断来源（e.currentTarget 是绑定监听的元素）；2）不冒泡的事件（focus/blur、mouseenter/mouseleave）不能用委托，可用捕获或 focusin/focusout 替代。面试常考：手写事件委托、target 与 currentTarget 区别、哪些事件不冒泡。', '浏览器,事件', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (746, 11, 0, 0, 3, 2, '解释 Web Workers 的通信机制和使用限制。', '', 0, 0, 'Web Worker 是浏览器提供的一种多线程方案，允许在后台线程运行 JS，避免耗时计算阻塞主线程（UI 线程）。通信机制：主线程 new Worker("worker.js") 创建 worker，用 worker.postMessage(data) 发送、worker.onmessage 接收；worker 内部用 self.onmessage 接收、self.postMessage 发送。消息通过"结构化克隆算法"传递（支持对象、数组、Map 等，但不支持函数、DOM 节点、原型链方法）。限制：1）不能访问 DOM 和 BOM（document/window 不可用）；2）脚本需符合同源策略（可用 Blob URL 绕过）；3）worker 不能直接操作页面。优化技巧：1）使用 Transferable Objects（如 ArrayBuffer）实现零拷贝传输，避免大对象克隆开销；2）合并消息减少通信次数；3）worker 内做复杂计算、图像处理、数据解析。适用场景：大数据量计算、加密、图片/视频处理、FFmpeg.wasm 等 CPU 密集型任务。面试常考：worker 能做什么不能做什么、postMessage 传大数据的性能。', '浏览器,多线程', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (747, 11, 0, 0, 2, 1, 'localStorage 的数据在浏览器关闭后仍然存在，而 sessionStorage 在标签页关闭后被清除。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', '浏览器,存储', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (748, 10, 0, 0, 3, 1, '解释一下 JSONP 的原理。', '', 0, 0, 'JSONP（JSON with Padding）是一种跨域解决方案，核心原理是利用 script 标签不受同源策略限制的特性。流程：1）前端动态创建 script 标签，src 指向目标接口并在 URL 上带回调函数名（如 ?callback=handleData）；2）服务器收到请求后，把数据包装成调用该回调函数的 JS 代码返回（如 handleData({name:"张三"})）；3）浏览器加载这段 script 自动执行，前端定义的 handleData 函数就拿到数据。优点：兼容性好、实现简单。缺点：1）只支持 GET（script 标签只有 GET）；2）有安全隐患，可能被恶意代码注入（需校验回调函数名白名单）；3）错误处理不便，难以监听失败状态；4）依赖服务端配合。现在主流跨域方案是 CORS 或代理服务器，JSONP 已较少使用，但在旧系统兼容场景仍会出现。面试常考：JSONP 原理、为什么只能 GET、与 CORS 对比。', 'HTTP,跨域', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (749, 10, 0, 0, 3, 1, '什么是 CORS？', '', 0, 0, 'CORS（Cross-Origin Resource Sharing，跨域资源共享）是浏览器与服务器共同遵守的跨域访问规范。原理：浏览器发现跨域请求时，会检查服务器返回的响应头中是否包含允许跨域的声明，主要响应头：Access-Control-Allow-Origin（允许的来源）、Access-Control-Allow-Methods（允许的方法）、Access-Control-Allow-Headers（允许的请求头）、Access-Control-Allow-Credentials（是否允许携带凭证/cookie）。简单请求（如满足条件的 GET/POST）直接发出，浏览器检查响应头放行；复杂请求（带自定义头、非简单 Content-Type、携带凭证）浏览器会先发 OPTIONS 预检请求，服务器允许后才发真实请求。前端无需额外配置，主要由后端设置响应头解决。生产环境推荐用 CORS 解决跨域，比 JSONP 更安全、支持所有请求方法。面试常考：CORS 响应头有哪些、预检请求触发条件、带 cookie 的跨域。', 'HTTP,跨域', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (750, 10, 0, 0, 3, 1, '什么是同源策略？', '', 0, 0, '同源策略（Same-Origin Policy）是浏览器的一项核心安全机制，用于隔离不同源的页面，防止恶意网站读取或篡改其他网站的数据。同源定义：两个 URL 的协议（protocol）、域名（host）、端口（port）三者都相同才算同源，只要有一个不同即为跨域。例如 http://a.com:80 与 https://a.com 不同源（协议和端口不同）。限制内容：1）不能读取其他源的 Cookie、localStorage、IndexedDB；2）不能操作其他源的 DOM；3）Ajax/Fetch 请求会被拦截（能发出但读不到响应）。为什么要同源策略：如果没有它，任意网站都能读取你登录的银行/社交网站的 Cookie 和数据，安全无从谈起。跨域解决方式：CORS（推荐）、JSONP（仅 GET）、代理服务器（前端 devServer/Nginx 反向代理）、postMessage（跨窗口通信）、WebSocket（不受同源限制）。面试常考：什么是同源、哪些能跨哪些不能、如何安全地跨域。', 'HTTP,跨域', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (751, 10, 0, 0, 2, 1, 'HTTP 状态码 200 表示请求成功，404 表示资源未找到，500 表示服务器内部错误。', '[{"code":"正确","value":""},{"code":"错误","value":""}]', 0, 0, '正确', 'HTTP,状态码', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (752, 0, 0, 1, 3, 1, 'import 和 require 有什么区别？', '', 0, 0, 'import 和 require 分别是 ES Module 和 CommonJS 两种模块化规范的引入语法，核心区别在加载时机和机制。require（CommonJS）：1）运行时加载，模块在代码执行到该语句时才被加载，可写在条件语句中动态加载；2）同步加载，加载完才继续执行，适合服务端（Node 默认）；3）导出的是值的拷贝（module.exports）；4）已加载模块会被缓存。import（ES Module）：1）静态加载，import 声明会被提升，编译阶段就确定依赖关系，不能动态条件导入（可用 import() 实现按需加载）；2）支持 tree-shaking，因静态可分析能剔除未使用导出，减小打包体积；3）导出的是值的引用，支持具名导出和默认导出；4）浏览器原生支持，天然异步加载不阻塞。Node 现在也支持 ES Module（.mjs 或 type: module）。面试常考：两者加载时机、循环引用处理差异、tree-shaking 原理。', 'JS,模块化', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (753, 0, 0, 1, 3, 1, 'ES Modules 相比 CommonJS 有哪些优势？', '', 0, 0, 'ES Modules（ESM）相比 CommonJS 有以下几个核心优势：1）静态分析、支持 tree-shaking：ESM 的 import/export 是静态声明的，打包工具在编译期就能确定哪些导出被使用，从而剔除未用代码减小体积；CommonJS 的 require 是运行时动态的，无法静态分析。2）异步加载：浏览器原生支持 ESM，import 天然异步不阻塞渲染；CommonJS 的 require 是同步的，浏览器端需打包器才能用。3）语法简洁、标准统一：ESM 是 ECMAScript 语言标准，有具名导出、默认导出、命名空间导入等清晰语法；CommonJS 只是社区约定。4）循环依赖处理更好：ESM 通过实时绑定在循环引用时能正确取到已初始化的导出；CommonJS 循环依赖时可能拿到未完成初始化的对象。5）导出是实时绑定：源模块值变化能反映到导入方；CommonJS 是值的拷贝。如今 Node 与打包器已全面支持 ESM，新项目默认使用 ESM。面试常考：tree-shaking 原理、循环依赖处理。', 'JS,模块化', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:25:51 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (754, 5, 0, 0, 3, 2, 'Vue2 的响应式原理是什么？有什么局限性？', '', 0, 0, 'Vue 2 的响应式基于 Object.defineProperty，通过给对象的每个属性定义 getter/setter 来劫持读写：组件渲染读取属性时在 getter 中收集依赖（Dep/Watcher），属性被修改时在 setter 中通知依赖更新，驱动视图重渲染。局限性：1）只能劫持对象已存在的属性，新增/删除属性无法被监听，必须用 Vue.set/Vue.delete 补丁处理；2）无法监听数组下标赋值和 length 变化，只能重写 push、pop、shift、unshift、splice、sort、reverse 七个数组方法；3）初始化时需递归遍历对象所有属性完成劫持，嵌套层级深时开销大、初始化慢；4）无法监听 Map、Set 等新数据结构。这些局限是 Vue 3 改用 Proxy 的直接原因。面试常考：Vue2 数组为何要重写方法、Vue.set 的用途、与 Proxy 对比。', 'Vue,响应式', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (755, 5, 0, 0, 3, 1, 'Vue 组件通信方式有哪些？', '', 0, 0, 'Vue 组件通信方式可归纳为几类：1）父传子：props 传递数据（单向数据流），子组件通过 defineProps/props 接收；2）子传父：子组件通过 $emit 触发自定义事件，父组件监听处理，配合 props 形成闭环；3）跨级/兄弟通信：事件总线（mitt、EventBus，已不推荐）、provide/inject（依赖注入，适合祖先向后代注入数据，适合深层组件）；4）全局状态管理：Vuex/Pinia 用于多个组件共享的复杂状态；5）其他：ref 获取子组件实例直接调用方法（Vue3 中 setup 暴露）、v-model 语法糖实现父子双向绑定、插槽（slot）传递内容模板。选择建议：简单层级用 props/emit，深层嵌套用 provide/inject，跨组件共享复杂状态用 Pinia，避免滥用事件总线导致数据流难以追踪。面试常考：props 单向数据流、v-model 本质、provide/inject 的响应式。', 'Vue,通信', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (756, 5, 0, 0, 3, 1, 'Vue 中 computed 和 watch 的区别是什么？', '', 0, 0, 'computed 和 watch 都用于监听数据变化，但定位不同。computed（计算属性）：1）基于已有响应式数据派生新值，有缓存——依赖不变时多次访问直接返回缓存结果，只有依赖变化才重新计算；2）适合模板中复杂的表达式和派生数据（如过滤列表、求和）；3）是声明式的，get 返回计算值，可带 setter 实现反向修改。watch（侦听器）：1）监听某个数据的变化，在变化时执行回调（可拿到新值和旧值）；2）适合执行副作用或异步操作，如请求接口、DOM 操作、路由跳转；3）是命令式的，关注"数据变化后要做什么"。区别总结：computed 关注"根据已有数据算什么"，有缓存、用于渲染；watch 关注"数据变了做什么"，无缓存、用于副作用。能 用 computed 尽量用 computed，因为它有缓存性能更好。面试常考：computed 缓存原理、watch 的 deep/immediate 选项、两者能否互相替代。', 'Vue,计算属性', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (757, 5, 0, 0, 3, 2, 'Vue 的 nextTick 原理是什么？为什么要用它？', '', 0, 0, 'nextTick 是 Vue 提供的工具，用于在 DOM 更新完成后执行回调。为什么要用它：Vue 的 DOM 更新是异步的——当数据变化时，Vue 不会立即更新 DOM，而是把更新任务放入一个队列（基于微任务），在下一个 tick 统一批量更新（这是性能优化，避免同一事件循环内多次修改数据导致多次渲染）。所以在修改数据后立即读取 DOM，拿到的是更新前的旧值，nextTick 回调中读取才是更新后的最新 DOM。原理：Vue 会维护一个异步任务队列（jobQueue），同一 tick 内多次数据变化只触发一次更新；nextTick 的实现依次尝试 Promise.then（微任务）、MutationObserver、setImmediate、setTimeout 降级方案，把回调推到更新队列之后执行。使用场景：数据修改后需要操作 DOM（如滚动位置、获取元素宽高）、配合第三方库初始化。面试常考：为什么 DOM 更新是异步的、nextTick 实现原理、微任务与宏任务优先级。', 'Vue,原理', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (758, 5, 0, 0, 3, 1, 'Vuex 有哪些核心概念？mutation 和 action 有什么区别？', '', 0, 0, 'Vuex 的核心概念包括：state（单一数据源，存放共享状态）、getters（类似计算属性，派生状态）、mutations（唯一能修改 state 的方式，同步函数）、actions（提交 mutation，可包含异步逻辑）、modules（模块化拆分）。mutation 与 action 的区别：1）职责不同——mutation 只能做同步的 state 修改，action 可以包含异步操作（请求接口、定时器），异步完成后调用 commit 提交 mutation 来改 state；2）写法不同——mutation 用 commit("类型", payload) 触发，action 用 dispatch("类型", payload) 触发；3）目的不同——把"改状态"和"做什么（含异步）"分离，保证 state 变更可追溯、可调试（DevTools 能记录每次 mutation）。面试常考：为什么 mutation 必须是同步的（保证 DevTools 能追踪状态变化的时间点）、action 内如何提交多个 mutation。', 'Vue,Vuex', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (759, 5, 0, 0, 3, 1, 'Vue3 的响应式原理是什么？相比 Vue2 有什么优势？', '', 0, 0, 'Vue 3 的响应式基于 ES6 Proxy，直接代理整个对象，拦截 get/set/deleteProperty/has 等操作：get 拦截收集依赖（track），set 等拦截触发更新（trigger），并能监听到属性新增、删除、数组下标和 length 变化。相比 Vue 2 的优势：1）无需 Vue.set/Vue.delete 处理新增删除属性，对象操作更自然；2）数组无需重写方法，下标赋值、push/pop 等都能自动响应；3）支持 Map、Set 等新数据结构；4）惰性代理——只有访问到某个属性才对其建立响应式，避免 Vue2 初始化递归遍历所有属性的开销，性能更好；5）对嵌套对象按需代理，深层对象性能更优。整体上 API 更简洁、能力更强、性能更好，是 Vue 3 响应式重构的核心。面试常考：Proxy 的 trap、ref 与 reactive 底层关系、与 Vue2 的差异。', 'Vue3,响应式', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (760, 5, 0, 0, 3, 1, 'ref 和 reactive 有什么区别？如何选择？', '', 0, 0, 'ref 和 reactive 都是 Vue 3 创建响应式数据的 API，区别在于使用对象类型和访问方式。reactive：只能用于对象（object/array/Map/Set 等引用类型），返回的是一个响应式 Proxy，访问时直接 obj.xxx，无需额外包装，但解构会丢失响应式（需用 toRefs 保持）。ref：可以用于基本类型和对象，基本类型通过对象包裹（内部用 {value: xxx}），访问/修改都要通过 .value；在模板中 ref 会自动解包，直接写 refName 即可。底层：ref 本质是把值包装成对象后交给 reactive/Proxy 处理，reactive 是其基础。选择建议：基本类型用 ref；普通对象或数组建议用 reactive（但注意解构问题）；实际开发中不少人习惯统一用 ref（配合 script setup 更统一，toRefs 场景更少）。面试常考：ref 为什么要 .value、reactive 解构为什么丢响应式、两者如何互相转换。', 'Vue3,API', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (761, 5, 0, 0, 3, 1, 'Options API 和 Composition API 的区别是什么？如何选择？', '', 0, 0, 'Options API 和 Composition API 是 Vue 的两种代码组织方式。Options API（Vue 2/3 兼容）：把代码按选项划分，如 data、computed、methods、watch、生命周期钩子。优点是结构清晰、约定明确，适合中小型组件和初学者；缺点是同一逻辑的代码被分散在不同选项中，当组件变复杂时，一个功能的 data/methods/watch 需要来回切换查看，可维护性下降。Composition API（Vue 3 引入）：通过 setup 函数按"逻辑关注点"组织代码，同一功能的响应式数据、计算属性、方法、监听写在一起，并通过自定义 hook（useXxx）把逻辑抽取复用。优点是逻辑内聚、复用性强（可替代 mixin，且无命名冲突）、对 TypeScript 支持更好、大型复杂组件更易维护。选择建议：新项目、复杂组件推荐 Composition API；简单组件两者皆可；Vue 官方建议 Composition API 是未来方向。面试常考：为什么需要 Composition API、与 mixin 对比、setup 的执行时机。', 'Vue3,API', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (762, 5, 0, 0, 3, 1, 'Pinia 相比 Vuex 有哪些优势？', '', 0, 0, 'Pinia 相比 Vuex 的优势：1）更简单的 API——去掉了 mutations，state、getters、actions 平铺在 store 中，修改状态直接 state.xxx = 值 或调用 action，无需像 Vuex 那样必须走 commit mutation，学习成本低；2）更好的 TypeScript 支持——类型推导更完善，几乎不需要额外类型声明；3）更轻量——没有 modules 嵌套的概念，store 是平级的，天然支持模块化且体积更小；4）支持 Composition API 风格——在 setup 中直接使用，也支持 Options 风格，更灵活；5）DevTools 支持好，且支持热更新（HMR）。底层：Pinia 基于 Vue 3 的 reactive，也是官方推荐的新一代状态管理库，Vuex 已进入维护模式。面试常考：Pinia 为何去掉 mutations、storeToRefs 的作用、与 Vuex 的迁移区别。', 'Vue3,Pinia', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (763, 5, 0, 0, 3, 1, 'vue-router 的 hash 模式和 history 模式有什么区别？', '', 0, 0, 'vue-router 的 hash 模式和 history 模式是两种前端路由实现方式。hash 模式：URL 中带 # 号（如 http://a.com/#/home），路由变化只改变 hash 部分，浏览器不会向服务器发送新请求，利用 hashchange 事件监听变化，前端自己渲染对应组件。优点是无需服务器配置、兼容性好、部署简单；缺点是 URL 不够美观、带 # 号，且不参与 SEO。history 模式：基于 HTML5 History API（pushState/replaceState + popstate 事件），URL 干净无 #（如 http://a.com/home）。优点是 URL 美观、利于 SEO；缺点是刷新或直接访问深层路径时，服务器需配置将所有路由都 fallback 到 index.html（否则 404），需要后端配合。选择建议：正式项目一般用 history（配合服务器配置）；无法控制服务器或纯静态部署时用 hash。面试常考：两者原理、history 刷新 404 的原因与解决方案。', 'Vue,路由', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (764, 5, 0, 0, 3, 1, 'v-if 和 v-for 的优先级？key 有什么作用？', '', 0, 0, 'Vue 3 中 v-if 的优先级高于 v-for（Vue 2 中是 v-for 优先，两者同时使用时 Vue 2 会有警告），官方不建议在同一元素上同时使用两者。原因：v-if 需要先判断是否渲染，而 v-for 已经生成了多个节点，两者混用逻辑混乱且性能差。正确做法：外层用 template 包裹，先 v-for 再在内部元素上用 v-if，或用 computed 先过滤再渲染（更推荐）。key 的作用：1）作为虚拟 DOM 中节点的唯一标识，Diff 算法据此判断节点是复用还是重建——相同 key 的节点尽量复用（只更新变化部分），不同 key 则销毁重建；2）没有 key（或使用 index）时，列表顺序变化可能复用错误的节点，导致状态错乱、性能差。建议：key 用稳定且唯一的业务 id，避免用 index（列表增删排序时易出问题）。面试常考：key 为什么不能用 index、v-for 中 v-if 的优先级。', 'Vue,指令', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (765, 4, 0, 0, 3, 1, '虚拟 DOM 和真实 DOM 的区别？Diff 算法策略是什么？', '', 0, 0, '虚拟 DOM 是对真实 DOM 的 JavaScript 对象描述（用 plain object 表示节点树），真实 DOM 是浏览器渲染出的实际节点树。区别：1）真实 DOM 操作开销大（每次改动都可能引起重排重绘），虚拟 DOM 只是普通 JS 对象，操作成本低；2）虚拟 DOM 可以在内存中计算出最小变更（Diff），再批量更新真实 DOM，减少不必要的操作；3）虚拟 DOM 天然跨平台（React Native、小程序可用同一套逻辑渲染到不同平台）。Diff 算法策略（React 的优化，将 O(n^3) 降为 O(n)）：1）只对同层节点比较，不跨层级比较；2）不同类型元素直接替换（不同 tag 不继续 diff）；3）同类型元素通过 key 判断是否复用——用 key 标识节点，尽量复用移动而非重建；4）列表 Diff 基于 key 进行移动、插入、删除。面试常考：为什么需要虚拟 DOM、Diff 的三条策略、key 的作用。', 'React,虚拟DOM', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (766, 4, 0, 0, 3, 2, 'React Fiber 架构解决了什么问题？', '', 0, 0, 'React Fiber 是 React 16 重写的协调引擎（reconciler），解决了旧架构（Stack Reconciler）的问题。旧架构的问题：协调（diff）和渲染是同步递归进行的，一旦开始更新，会一直递归到结束，期间无法中断，如果组件树很大，会长时间占用主线程，导致页面卡顿、掉帧，无法响应高优先级操作（如输入）。Fiber 解决的问题：1）可中断——把更新拆分成一个个小的 Fiber 工作单元（链表结构），可以暂停、让出主线程给浏览器渲染和响应输入，再恢复；2）可调度优先级——支持给不同更新设优先级（如输入高优先级、数据加载低优先级），高优先级可打断低优先级；3）支持并发特性——为时间切片（Time Slicing）、Suspense、并发渲染（Concurrent Mode）奠定基础。核心数据结构是 Fiber 树（单向链表），通过 beginWork/completeWork 遍历。面试常考：Fiber 如何实现可中断、时间切片原理、与旧架构对比。', 'React,架构', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (767, 4, 0, 1, 3, 1, 'useEffect 和 useLayoutEffect 有什么区别？', '', 0, 0, 'useEffect 和 useLayoutEffect 的区别在于执行时机。useEffect：在浏览器完成绘制之后异步执行（即 DOM 更新并绘制完成后再跑），不阻塞渲染。适合网络请求、订阅、日志等不需要同步操作 DOM 的副作用；因为异步，可能造成视觉闪烁（先渲染旧内容再更新）。useLayoutEffect：在浏览器绘制之前同步执行（DOM 变更后、绘制前），会阻塞渲染。适合需要在浏览器绘制前同步读取/修改 DOM 的场景，如测量元素尺寸、设置滚动位置、避免闪烁的布局调整。共同点：都是副作用钩子，用法一致（传依赖数组、返回清理函数）。使用建议：绝大多数情况用 useEffect；只有当副作用需要在浏览器绘制前同步完成（否则会闪烁或产生错误布局）时才用 useLayoutEffect。面试常考：两者执行时机、什么时候必须用 useLayoutEffect、SSR 警告。', 'React,Hooks', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (768, 4, 0, 0, 3, 2, 'React.memo、useMemo、useCallback 有什么区别？', '', 0, 0, 'React.memo、useMemo、useCallback 都是 React 的性能优化手段，作用范围不同。React.memo：高阶组件，用于包裹函数组件，对 props 做浅比较——父组件重渲染时，如果 props 没变，则跳过子组件重渲染。useMemo：用于缓存计算结果，传入依赖数组，只有依赖变化时才重新计算，适合昂贵的计算。useCallback：用于缓存函数引用，只有依赖变化时才返回新的函数，配合 React.memo 使用（父组件每次渲染都创建新函数，会导致 memo 失效）。区别：memo 缓存"组件"，useMemo 缓存"值/计算结果"，useCallback 缓存"函数"。注意：三者都只是优化，不应滥用——过度使用反而增加内存和比较开销。最佳实践：先解决重渲染问题，再在关键位置使用；useCallback 通常与子组件 memo 配合才有效果。面试常考：memo 失效原因、useMemo 与 useCallback 区别、何时该用。', 'React,性能', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (769, 4, 0, 0, 3, 2, '如何排查和解决 React 应用的重渲染问题？', '', 0, 0, '排查 React 重渲染问题，一般从工具和思路两方面入手。工具：1）React DevTools 的 Profiler 面板，录制交互，看哪些组件被渲染、耗时多少，找出不必要的重渲染；2）React.memo 配合 console.log 或 useWhyDidYouUpdate 类工具对比 props。常见原因与解决：1）父组件每次渲染都创建新对象/数组/函数（如内联对象、箭头函数），导致子组件 props 引用变化——用 useMemo/useCallback 稳定引用；2）未用 React.memo 包裹子组件——用 memo 做浅比较；3）state 放在过高层级——把状态下放到真正需要的组件，或用 Context 拆分（Context 值变化会触发所有消费者）；4）整个页面用单一 Context——拆成多个粒度更细的 Context 或使用 state 管理库（zustand 等按需订阅）；5）key 使用不当导致组件重建——用稳定 id。补充：真正常见的"性能问题"往往是没加 memo + 内联函数。面试常考：重渲染触发条件、memo/useCallback 配合使用。', 'React,性能', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (770, 8, 0, 0, 3, 1, 'TypeScript 中 interface 和 type 有什么区别？如何选择？', '', 0, 0, 'TypeScript 中 interface 和 type 都能定义类型，区别：interface：1）只能描述对象/函数/类的结构；2）支持 extends 继承（接口继承接口、类实现）；3）支持声明合并——同名 interface 自动合并，利于扩展第三方库类型；4）更贴近 OOP 语义。type：1）更灵活，可定义联合类型、交叉类型、元组、字面量、基本类型别名等任意组合类型；2）不可重复声明同名 type（重复报错）；3）通过交叉（A & B）可模拟继承但语义上不是"继承"；4）支持映射类型、条件类型等高级类型编程。选择建议：描述对象结构、需要继承/合并、类相关用 interface；需要联合、交叉、元组或类型编程用 type。社区实践：库作者常用 interface 定义对外 API 结构（可合并扩展），内部类型用 type。面试常考：两者能力差异、声明合并、什么时候混用。', 'TS,类型', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (771, 8, 0, 0, 3, 2, '什么是泛型？有哪些常见约束？', '', 0, 0, '泛型（Generics）是在定义函数、接口、类时不预先指定类型，而在使用时传入类型参数，从而在保证类型安全的同时提高复用性。示例：function identity<T>(arg: T): T { return arg; } identity<string>("hi")，T 由调用时推断。常见约束（extends）：1）T extends SomeType——限制泛型必须是某种类型的子集，如 T extends Lengthwise（必须有 length 属性）；2）keyof——取对象键的联合类型，用于约束泛型必须是对象的某个键，如 function get<T, K extends keyof T>(obj: T, key: K)；3）默认类型参数：function f<T = string>()。常见工具类型：Partial（全部可选）、Required（全部必选）、Readonly、Pick（挑属性）、Omit（排除属性）、Record、ReturnType（取函数返回类型）等。面试常考：泛型约束的写法、内置工具类型实现（如手写 Partial）、泛型与 any 的区别。', 'TS,泛型', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (772, 1, 0, 0, 3, 1, 'CSS 盒模型是什么？content-box 和 border-box 有什么区别？', '', 0, 0, 'CSS 盒模型描述元素在页面上的占位结构，由 content（内容）、padding（内边距）、border（边框）、margin（外边距）四部分组成。content-box 与 border-box 的区别在于 width/height 的计算范围。content-box（默认）：width/height 只包含内容区 content，padding 和 border 另算，所以实际占用的总宽度 = width + padding + border；给元素设置 width:100px + padding:20px + border:1px 时，实际渲染宽度是 142px，容易导致布局超出预期。border-box：width/height 包含 content + padding + border（即 padding 和 border 从宽度中扣除，向内挤压 content），元素实际总宽度始终等于设置的 width，布局更直观可控。现代开发普遍推荐全局设置 *{ box-sizing: border-box; }，配合弹性/栅格布局更不易出问题。面试常考：两者区别、盒模型计算、为什么推荐 border-box。', 'CSS,盒模型', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (773, 1, 0, 1, 3, 1, '什么是 BFC？有哪些应用场景？', '', 0, 0, 'BFC（Block Formatting Context，块级格式化上下文）是 CSS 中一个独立的渲染区域，区域内部的布局与外部的元素相互隔离，不会互相影响。触发 BFC 的条件：float 不为 none、overflow 不为 visible（如 auto/hidden）、display 为 inline-block/table-cell/flex/grid、position 为 absolute/fixed 等。BFC 的作用（应用场景）：1）清除浮动——父容器触发 BFC 后能包含浮动的子元素，不再塌陷高度；2）阻止 margin 塌陷——相邻块级元素的垂直 margin 会合并，BFC 隔离后内部 margin 不会溢出到外部；3）防止元素被浮动元素覆盖——给右侧元素设 overflow:hidden 触发 BFC，可形成两列自适应布局；4）阻止外部元素侵入。面试常考：BFC 触发条件有哪些、用 BFC 解决哪些经典布局问题（清除浮动、margin 塌陷）。', 'CSS,布局', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (774, 1, 0, 0, 3, 1, 'Flex 布局中 flex:1 代表什么？', '', 0, 0, 'flex:1 是 flex-grow、flex-shrink、flex-basis 三个属性的缩写，完整写法 flex: 1 1 0%。含义：1）flex-grow: 1——有剩余空间时按比例放大，占满剩余空间；2）flex-shrink: 1——空间不足时允许按比例缩小；3）flex-basis: 0%——初始主轴尺寸为 0（不基于内容），所以最终尺寸完全由 grow 分配决定。因此 flex:1 的效果是：该元素会在主轴方向上自动伸展，占满父容器分配给它的一份剩余空间，多个 flex:1 的兄弟元素会均分剩余空间（常用于等分布局、自适应高度/宽度，如侧边栏内容区撑满剩余高度）。对比：flex: 0 1 auto 是不伸缩（固定按内容）、flex: auto 是 1 1 auto（按内容再伸缩）。面试常考：flex:1 展开后的完整值、flex-grow/shrink/basis 各自作用、flex:1 与 flex:auto 区别。', 'CSS,Flex', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (775, 1, 0, 0, 3, 1, '如何实现元素的水平垂直居中？', '', 0, 0, '实现水平垂直居中有多种方案，按场景选择。1）flex 布局（最推荐）：父容器 display:flex; justify-content:center; align-items:center; 子元素不定宽高也能居中。2）grid 布局：父容器 display:grid; place-items:center; 一行搞定。3）绝对定位 + transform：子元素 position:absolute; top:50%; left:50%; transform:translate(-50%,-50%); 适合已知父容器为定位上下文、子元素尺寸未知的情况（不依赖自身尺寸）。4）绝对定位 + margin:auto：子元素 position:absolute; top:0; right:0; bottom:0; left:0; margin:auto; 需子元素有确定宽高。5）行内元素/文本：父 text-align:center + line-height 等于父高度。6）table-cell：父 display:table-cell; vertical-align:middle; text-align:center。推荐优先 flex/grid，兼顾兼容性时用绝对定位 + transform。面试常考：多种方案对比、transform 与 margin:auto 方案的适用条件。', 'CSS,布局', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (776, 11, 0, 0, 3, 2, '浏览器缓存机制：强缓存和协商缓存有什么区别？', '', 0, 0, '浏览器缓存分为强缓存和协商缓存两级。强缓存：命中后直接使用本地缓存，不发请求，状态码 200（from memory cache / from disk cache）。由响应头控制：Cache-Control（优先级更高，常用 max-age=秒数，如 max-age=3600，还有 no-cache/no-store 等）、Expires（HTTP/1.0，绝对过期时间，受本地时间影响）。协商缓存：强缓存过期后，浏览器带上验证信息发请求询问服务器资源是否变化。由服务器通过响应头返回：Last-Modified / If-Modified-Since（基于文件修改时间，精确到秒，粒度较粗）和 ETag / If-None-Match（基于内容哈希，更精确，优先级高于 Last-Modified）。服务器若判断资源没变，返回 304 Not Modified，浏览器继续用本地缓存；变了则返回 200 和新资源。两者关系：强缓存命中就不走协商；强缓存失效才走协商。面试常考：Cache-Control 与 Expires 优先级、ETag 与 Last-Modified 区别、304 的含义。', '浏览器,缓存', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (777, 11, 0, 0, 3, 1, 'localStorage、sessionStorage、cookie 有什么区别？', '', 0, 0, 'localStorage、sessionStorage、cookie 都是浏览器端存储，区别在生命周期、容量和传递方式。生命周期：localStorage 持久化存储，除非手动清除，否则一直保留（跨会话）；sessionStorage 会话级，关闭标签页/浏览器即清除；cookie 可设置过期时间（Expires/Max-Age），未设置则关闭浏览器清除。容量：localStorage/sessionStorage 约 5MB；cookie 约 4KB，且每次请求都会自动携带在 Cookie 头中，增加请求体积。作用域：三者都受同源策略限制；cookie 还可设置 path/domain 控制范围。存取方式：localStorage/sessionStorage 用 getItem/setItem 存字符串（对象需 JSON.stringify），cookie 用 document.cookie 读写字符串。用途：localStorage 存长期不敏感数据（主题、用户偏好）、sessionStorage 存会话内数据（表单草稿）、cookie 主要用于身份认证（配合 httpOnly 防 XSS 读取）和服务端会话标识。面试常考：三者对比、cookie 为什么不适合存大量数据、localStorage 安全性。', '浏览器,存储', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (778, 11, 0, 0, 3, 2, '什么是重排（回流）和重绘？如何避免？', '', 0, 0, '重排（回流，Reflow/Layout）是重新计算元素的几何位置和大小，重绘（Repaint/Paint）是重新绘制元素的外观（颜色、背景等）。重排一定会触发重绘，重绘不一定重排。触发重排的操作：1）增删改 DOM 元素；2）修改元素尺寸（宽高、padding、border、margin）或位置；3）修改窗口尺寸（resize）、字体大小变化；4）读取某些布局属性也会强制同步重排（offsetWidth、clientHeight、getBoundingClientRect、scrollTop 等，读取时会强制浏览器先完成布局）；5）display:none 隐藏元素、添加/移除样式类。触发重绘：颜色、背景、阴影、边框样式等视觉变化，不动几何。如何避免：1）合并 DOM 读写，用 DocumentFragment 批量操作；2）用 class 或 cssText 一次性修改样式而非逐条；3）把需要动画的元素用 transform 实现（transform 在合成层，不触发重排重绘）；4）避免频繁读取布局属性，缓存计算结果；5）用 display:none 先隐藏再操作；6）will-change/translateZ 提升为独立图层。面试常考：重排重绘区别、哪些操作触发重排、如何优化。', '浏览器,渲染', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (779, 10, 0, 0, 3, 2, 'HTTP/1.0、HTTP/1.1、HTTP/2.0、HTTP/3.0 有什么区别？', '', 0, 0, 'HTTP 各版本主要在传输效率和协议特性上迭代。HTTP/1.0：无状态、每个请求/响应后关闭连接，每次请求都要重新建立 TCP 连接，效率低。HTTP/1.1：1）默认持久连接（Keep-Alive），连接复用减少握手开销；2）支持管线化（pipelining，但响应仍需按序，队头阻塞）；3）新增 Host 头（支持虚拟主机）、分块传输（chunked）、断点续传（Range）。仍存在队头阻塞：一个连接上请求必须排队，前一个慢会影响后面的。HTTP/2.0：1）二进制分帧协议，替代文本协议；2）多路复用——一个 TCP 连接上并行发送多个请求/响应，解决队头阻塞（应用层）；3）头部压缩（HPACK）减少传输体积；4）服务器推送（Server Push）；5）流量优先级。但底层仍是 TCP，TCP 层丢包重传仍会造成队头阻塞。HTTP/3.0：基于 UDP 的 QUIC 协议，1）彻底解决队头阻塞（每个流独立）；2）0-RTT/1-RTT 快速握手，连接建立更快；3）内建 TLS 1.3、连接迁移（换网络不断连）。面试常考：各版本核心改进、队头阻塞的层次。', 'HTTP,协议', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (780, 10, 0, 0, 3, 1, 'HTTP 常见状态码有哪些？分别表示什么？', '', 0, 0, 'HTTP 状态码分五类：1xx 信息响应、2xx 成功、3xx 重定向、4xx 客户端错误、5xx 服务器错误。常见状态码：200 请求成功；201 已创建（POST 建资源）；204 无内容（成功但响应体为空）；301 永久重定向（URL 变了，后续用新地址，搜索引擎更新）；302 临时重定向（本次用新地址）；304 协商缓存命中（资源未修改，用本地缓存）；400 请求参数错误；401 未认证（未登录/凭证无效）；403 禁止访问（已认证但无权限）；404 资源不存在；405 方法不允许；429 请求过于频繁；500 服务器内部错误；502 网关错误（代理上游无响应）；503 服务不可用（过载/维护）；504 网关超时。判断优先级：见到 4xx 排查前端请求是否正确，5xx 排查服务器/后端。面试常考：301/302 区别、401 与 403 区别、304 与缓存的关系。', 'HTTP,状态码', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (781, 10, 0, 0, 3, 2, 'HTTPS 的工作原理是什么？', '', 0, 0, 'HTTPS 的工作原理是在 HTTP 与 TCP 之间增加 SSL/TLS 层，通过混合加密保证安全。流程：1）客户端发起请求（ClientHello），携带支持的加密套件和随机数；2）服务器返回证书（含公钥、域名、CA 签名）和随机数（ServerHello）；3）客户端验证证书是否可信（CA 链、有效期、域名是否匹配），验证通过后生成会话密钥（或用 DH/ECDHE 算法协商预主密钥，经非对称加密传给服务器）；4）双方用预主密钥 + 两个随机数推导出对称会话密钥；5）之后所有数据用对称加密（AES）加密传输，并带 MAC/签名保证完整性。核心思想："非对称加密（RSA/ECDHE）协商出安全的对称密钥，对称加密（AES）高效传输数据"。之所以不用纯非对称：非对称加解密慢、不适合大数据量；不用纯对称：密钥如何安全传递无法解决。面试常考：混合加密原因、证书的作用与验证过程、TLS 握手步骤。', 'HTTP,HTTPS', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (782, 10, 0, 0, 3, 2, '什么是预检请求（OPTIONS）？', '', 0, 0, '预检请求（Preflight）是 CORS 机制的一部分，用于"复杂请求"发起前的探测。触发条件：当跨域请求满足以下任一条件时，浏览器会先发 OPTIONS 预检请求：1）请求方法不是简单方法（GET、HEAD、POST 之外，如 PUT、DELETE、PATCH）；2）自定义请求头（非简单头，如 Authorization、X-Token、Content-Type 为 application/json）；3）Content-Type 不在简单类型（text/plain、multipart/form-data、application/x-www-form-urlencoded）中。流程：浏览器先发 OPTIONS 请求（携带 Access-Control-Request-Method、Access-Control-Request-Headers），服务器响应 Access-Control-Allow-Methods、Access-Control-Allow-Headers、Access-Control-Allow-Origin，浏览器确认允许后才发送真实请求。作用：在真正请求前让服务器明确声明是否允许该跨域请求，避免服务器无意中处理了不期望的跨域请求。优化：简单请求无需预检；或后端配置时把允许的方法/头写全，减少预检次数。面试常考：什么情况下触发预检、预检请求的响应头、如何减少预检。', 'HTTP,跨域', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (783, 10, 0, 0, 3, 1, 'HTTP 常见的请求头和响应头有哪些？', '', 0, 0, 'HTTP 常见请求头：Host（目标主机）、User-Agent（浏览器/客户端标识）、Accept（可接受的内容类型）、Accept-Encoding（可接受的压缩方式，如 gzip）、Accept-Language（语言偏好）、Cookie（携带会话凭证）、Content-Type（请求体类型，如 application/json）、Content-Length（请求体长度）、Authorization（认证凭证，如 Bearer Token）、Referer（来源页面）、Origin（发起请求的来源，跨域判断用）、Cache-Control（缓存策略）、If-Modified-Since / If-None-Match（协商缓存验证）。常见响应头：Content-Type（响应体类型）、Content-Length、Content-Encoding（压缩方式）、Cache-Control / Expires（强缓存）、Last-Modified / ETag（协商缓存）、Access-Control-Allow-Origin（CORS 允许来源）、Set-Cookie（下发 Cookie）、Location（重定向地址）、Content-Disposition（文件下载文件名）。记忆技巧：请求头里"我想/我携带什么"，响应头里"我返回什么/允许什么"。面试常考：Content-Type 与 Accept 区别、CORS 相关头、缓存相关头。', 'HTTP,头部', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (784, 10, 0, 0, 3, 1, '如何解决跨域问题？', '', 0, 0, '解决跨域（浏览器同源策略限制）的常见方案：1）CORS（跨域资源共享）——主流方案，后端在响应头设置 Access-Control-Allow-Origin 等，支持所有请求方法和凭证，安全规范；前端无需配置。2）代理服务器——开发环境用 Vite/Webpack devServer 的 proxy 把 /api 代理到目标服务器（浏览器只看到同源），生产用 Nginx 反向代理转发，前端代码无感知。3）JSONP——利用 script 标签不受同源限制，只支持 GET、兼容老浏览器，现已较少用。4）postMessage——用于跨窗口/iframe 通信（window.postMessage + message 事件）。5）WebSocket——不受同源策略限制（但需服务端配合实现协议）。6）document.domain + iframe——子域间通信（已逐渐淘汰）。7）window.name / location.hash 传值——老旧方案。推荐：生产用 CORS 或 Nginx 代理，开发用 devServer proxy。面试常考：每种方案适用场景、CORS 与代理的取舍。', 'HTTP,跨域', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (785, 11, 0, 0, 3, 2, '如何优化首屏加载速度？', '', 0, 0, '首屏加载速度优化，核心是减少关键资源体积和缩短关键路径。策略：1）代码层面：路由懒加载（按需分包，首屏只加载当前页）、组件按需引入（antd/element 的按需加载）、Tree-shaking 去掉未用代码、避免同步引入大体积库。2）资源层面：压缩 JS/CSS/HTML（gzip/brotli）、压缩图片（WebP/压缩工具）或使用 CDN 加载静态资源、字体按需加载（font-display）。3）网络层面：HTTP/2 多路复用、合理设置缓存（强缓存 + 协商缓存）、预加载关键资源（preload/prefetch）、懒加载非首屏图片。4）渲染层面：减少阻塞渲染的脚本（defer/async）、内联首屏关键 CSS、SSR/预渲染（服务端渲染或静态生成，减少首屏白屏）。5）监控指标：用 Lighthouse 分析 LCP（最大内容绘制）、FCP（首次内容绘制）等指标，针对性优化。面试常考：前端性能指标有哪些、路由懒加载原理、如何减少白屏时间。', '性能优化,首屏', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (786, 11, 0, 0, 3, 2, '如何一次性渲染 10 万条数据保证页面不卡顿？', '', 0, 0, '一次性渲染 10 万条数据保证不卡顿，核心是"分批渲染 + 减少 DOM 节点"，常见方案：1）虚拟列表（虚拟滚动）——最推荐。只渲染可视区域内的条目（约几十条），通过计算滚动位置动态替换内容，配合固定/动态高度估算，无论数据多少 DOM 节点数恒定。代表库：vue-virtual-scroller、react-window、虚拟列表组件。2）分页加载——把 10 万条分成多页，用户滚动/点击加载更多，或按需加载。3）时间分片（Time Slicing）——如果必须一次性渲染，把渲染任务拆成多个片段，用 requestIdleCallback 或 setTimeout 分批插入 DOM（每次处理一小批，避免一次阻塞主线程）。4）文档片段（DocumentFragment）——批量创建节点后一次性插入，减少重排次数。5）虚拟 DOM 框架的优化——Vue/React 的 diff 本身有开销，配合 key 复用节点。注意：不要用一次性 append 10 万个 DOM 节点，会触发大量重排导致卡死。面试常考：虚拟列表原理、时间分片、为什么大量 DOM 会卡顿。', '性能优化,大数据', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (787, 11, 0, 0, 3, 2, '如何实现大文件上传？', '', 0, 0, '大文件上传的核心思路是"分片上传 + 断点续传 + 秒传"。整体方案：1）前端将大文件按固定大小（如 5MB）切成多个分片，用 Blob.slice 实现；2）逐片上传，每片可附带 hash（如用 SparkMD5 计算整个文件或分片的 hash）；3）后端接收分片暂存（临时目录），全部传完后通知合并；4）断点续传——上传前先请求服务器查询已上传的分片，只上传缺失的分片（本地记录已传分片）；5）秒传——上传前把文件 hash 发给服务器，若服务器已有该文件（其他人传过），直接返回已存在，前端跳过上传。6）并发控制——限制同时上传的分片数（如 3-5 个），避免连接数过多；7）进度展示——根据已传分片数/总大小计算整体进度。8）失败重试——单个分片失败自动重试。9）可选：文件完整性校验（全部传完对比总 hash）。面试常考：分片大小如何选择、如何保证断点续传、秒传实现原理、并发上传的控制。', '性能优化,上传', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (788, 11, 0, 0, 3, 1, '如何防止按钮重复点击？', '', 0, 0, '防止按钮重复点击，常见方案按场景分：1）提交时禁用按钮——最简单直接：点击后立即置 disabled，等请求完成/失败后再恢复；或用 loading 状态（Element/Antd 按钮自带 loading 属性），避免用户在请求期间再次点击。2）防抖（debounce）——把短时间内的多次点击合并成一次，适合非提交类的连续点击（如"获取验证码"按钮，点击后倒计时）。3）节流（throttle）——限制一定时间内最多触发一次。4）请求层控制（更可靠）——不依赖 UI 状态，在请求封装层用请求锁：同一接口未返回前忽略后续调用（用一个标志位或 Map 记录进行中的请求），可覆盖回车、双击、快捷键等绕过按钮状态的场景。5）后端幂等性兜底——前端防重只是体验优化，真正的保障是后端接口幂等（相同请求只生效一次，如用唯一请求 ID 去重）。推荐组合：UI 禁用 + 请求层锁 + 后端幂等。面试常考：前端防重方案、为什么需要后端幂等。', '性能优化,交互', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (789, 11, 0, 1, 3, 1, '如何实现移动端适配？', '', 0, 0, '移动端适配的核心目标：让页面在不同屏幕宽度/分辨率下保持合理布局与可读性。主流方案：1）viewport 设置——<meta name="viewport" content="width=device-width, initial-scale=1.0">，让布局宽度等于设备宽度、禁止缩放，是所有方案的前提。2）rem 适配——以根元素（html）的 font-size 为基准，用 rem 写尺寸，通过 JS 或媒体查询动态设置根字号（如按屏幕宽度 / 设计稿宽度 × 100），实现等比缩放。经典：flexible.js 方案（设计稿 750）。3）vw/vh 适配——直接用 vw（视口宽度的 1%）等单位，天然随视口变化，无需 JS 计算，配合 rem 混合使用（边界情况用 vw）。4）百分比 + flex 弹性布局——宽度自适应，内容区用 flex/grid 弹性伸缩。5）媒体查询（Media Query）——按断点（如 768px/1024px）切换布局，常用于响应式站点（一套代码多端适配）。6）图片适配——srcset/sizes、CDN 按需裁剪，Retina 屏用 2x/3x 图。7）安全区适配——iOS 刘海屏用 env(safe-area-inset-*)。面试常考：rem 与 vw 方案原理、1px 问题、设计稿换算。', '移动端,适配', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (790, 10, 0, 0, 3, 2, 'XSS 攻击是什么？如何防御？', '', 0, 0, 'XSS（跨站脚本攻击）指攻击者把恶意脚本注入页面并执行，窃取用户数据。分类：1）存储型——恶意脚本被存在服务端（如评论、帖子内容），所有访问该页面的用户都会中招，危害最大；2）反射型——恶意脚本在 URL 参数中，诱导用户点击带恶意参数的链接，脚本随响应反射回页面执行，不持久存储；3）DOM 型——攻击脚本通过修改 DOM 触发（如 location.hash、innerHTML），纯前端漏洞，服务端不可见。防御：1）输入过滤——对用户输入做白名单校验、转义 HTML 特殊字符（< > & "），尤其在插入 innerHTML/v-html/dangerouslySetInnerHTML 前；2）输出编码——渲染时对用户数据编码（框架默认转义文本内容）；3）CSP（内容安全策略）——设置 Content-Security-Policy 限制可执行的脚本来源，即使注入也无法执行；4）HttpOnly Cookie——关键凭证 cookie 加 HttpOnly，JS 无法读取，降低窃取风险；5）避免使用 eval、new Function、document.write 等危险 API。面试常考：三类 XSS 区别、为什么 v-html 有风险、CSP 的作用。', '安全,XSS', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (791, 10, 0, 0, 3, 2, 'CSRF 攻击是什么？如何防御？', '', 0, 0, 'CSRF（跨站请求伪造）指攻击者诱导已登录用户在不知情的情况下，向目标网站发送伪造请求，利用用户的登录态执行恶意操作（如转账、改密）。攻击原理：用户在 A 网站已登录（浏览器持有 A 的 Cookie），攻击者构造一个指向 A 的恶意请求页面（图片 src 或表单自动提交），用户访问该页面时，浏览器自动携带 A 的 Cookie 发出请求，A 无法区分请求是否用户本人发起（Cookie 自动带上）。常见防御：1）CSRF Token——服务器下发随机 token 到页面，请求时必须携带（攻击者跨站无法读取 token）；2）SameSite Cookie——设置 Set-Cookie: SameSite=Lax/Strict，跨站请求不携带 Cookie，浏览器原生防御；3）校验 Origin/Referer——服务端校验请求来源是否为白名单域名；4）自定义请求头——要求请求带自定义头（如 X-Requested-With），跨站表单/图片无法设置；5）二次验证——敏感操作（转账、改密）要求输入密码/验证码。与 XSS 区别：XSS 是脚本注入执行，CSRF 是利用登录态伪造请求。面试常考：CSRF 原理、与 XSS 区别、防御手段优先级。', '安全,CSRF', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (792, 7, 0, 0, 3, 1, 'Webpack 的五大核心概念是什么？', '', 0, 0, 'Webpack 的五大核心概念：1）Entry（入口）——指定打包的起点文件，Webpack 从这里开始分析依赖图，可配置单入口或多入口。2）Output（输出）——配置打包产物的输出位置和文件名（如 dist/bundle.js），可配置 hash、多出口。3）Loader（加载器）——Webpack 本身只理解 JS，loader 把各种资源（CSS、图片、字体、TS、Vue 等）转换为模块，可链式使用，在模块编译阶段执行。4）Plugin（插件）——在打包整个生命周期（各钩子阶段）执行复杂任务：代码压缩、HTML 生成、环境变量注入、分包、提取 CSS 等，比 loader 作用范围更广。5）Mode（模式）——development / production / none，决定内置优化：production 自动压缩混淆、tree-shaking、作用域提升；development 开启 source-map、热更新。理解这五点就能看懂大部分 webpack 配置。面试常考：loader 与 plugin 区别、mode 的作用、配置结构。', 'Webpack,概念', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (793, 7, 0, 0, 3, 1, 'Webpack 打包优化有哪些手段？', '', 0, 0, 'Webpack 打包优化的方向分为"减小体积"和"加快速度"。减小体积：1）Tree-shaking——ES Module 静态分析剔除未使用代码（需用 ESM 且 production 模式）；2）代码压缩——TerserPlugin 压缩 JS、cssnano 压缩 CSS、html-minifier 压缩 HTML，开启 gzip/brotli 再压一层；3）代码分割（Code Splitting）——SplitChunksPlugin 提取公共依赖和第三方库（vendor）单独分包，按需加载；4）按需引入——组件库（antd/element）用 babel-plugin-import 等按需加载；5）移除无用依赖、启用 source-map 精简模式。加快构建：1）缓存——babel-loader 的 cacheDirectory、cache-loader、持久化缓存（cache: {type:"filesystem"}）；2）多进程——thread-loader 并行处理 loader、terser-webpack-plugin 的 parallel；3）缩小范围——resolve.alias 指定库路径、loader 的 include/exclude 只处理必要目录；4）HappyPack 或转用更快的打包器（Vite/esbuild 作为优化手段）。面试常考：tree-shaking 前提、分包策略、构建提速手段。', 'Webpack,优化', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (794, 7, 0, 0, 3, 2, 'Vite 为什么比 Webpack 快？', '', 0, 0, 'Vite 比 Webpack 快，核心在于开发环境不再做"打包"。原理：Webpack 开发时要把所有模块构建成依赖图再启动 dev server（冷启动慢，改代码整包或大范围重编译）；Vite 利用浏览器原生 ES Module 能力：1）启动时不做全量打包，只启动一个轻量的 dev server，按需对请求到的模块用 esbuild 预构建依赖（将 node_modules 依赖预打包为 ESM，避免成百上千个小文件请求）并即时转译（esbuild 用 Go 编写，转译速度比 Babel 快几十倍）；2）开发时源码按需加载——浏览器请求哪个文件，Vite 才转换哪个文件，天然实现按需编译，冷启动几乎秒开；3）HMR 更快——基于 ESM 的模块边界，改动只更新对应模块，不用刷新整个页面，且是原生速度。生产环境 Vite 用 Rollup 打包（保证产物优化）。结论：Vite 快在"开发不打包 + esbuild 转译 + 原生 ESM 按需加载"，而 Webpack 是"先全量打包再服务"。面试常考：Vite 为什么快、esbuild 与 Babel 对比、生产为何用 Rollup。', 'Vite,原理', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
INSERT INTO `questions` (`id`, `subjectID`, `catalogID`, `browses_num`, `questionType`, `difficulty`, `question`, `questionDetail`, `likes_num`, `favorite_num`, `answer`, `tags`, `chkState`, `chkRemarks`, `creator`, `creator_id`, `addDate`, `is_deleted`, `updateTime`, `updateUser`) VALUES (795, 7, 0, 0, 3, 2, 'Webpack 热更新（HMR）的原理是什么？', '', 0, 0, 'Webpack 热更新（HMR，Hot Module Replacement）指代码修改后，不刷新整个页面，只更新被修改的模块并保留应用状态。原理与流程：1）dev server 启动时，Webpack 编译产物，同时启动 WebSocket（ws）连接浏览器；2）监听文件变化——文件修改触发重新编译，生成新的模块代码；3）编译完成后，dev server 通过 WebSocket 向浏览器发送更新通知（包含更新模块的 hash 和清单）；4）浏览器收到后，通过 JSONP 向 dev server 拉取更新后的模块代码；5）模块更新前，执行旧模块的 dispose 清理钩子（如清除定时器）；6）判断模块是否接受热更新（hot.accept）：如果模块自身声明了 accept，则用新模块替换旧模块并执行；如果模块未被 accept（没有处理函数），则向上冒泡寻找能接受的父模块，都没有则触发整页刷新；7）React/Vue 通过各自的 HMR 插件（react-refresh、vue-loader 的热重载）把组件替换并保留 state。面试常考：HMR 完整流程、为什么保留 state、accept 冒泡机制。', 'Webpack,HMR', 1, NULL, 'admin', 1, 'Fri Aug 28 2026 00:28:28 GMT+0800 (中国标准时间)', 0, NULL, NULL);
